PAGES2 = [{'repo': 'ffmpeg', 'slug': 'install-ffmpeg-and-check-codecs', 'title': 'How to install FFmpeg and check which codecs your build has', 'scenario': 'Nothing else works until the ffmpeg binary is on your system — and not every build ships the same encoders.', 'code': 'brew install ffmpeg          # macOS\nsudo apt install ffmpeg     # Debian/Ubuntu\nwinget install ffmpeg       # Windows (winget)\nffmpeg -version                  # show version\nffmpeg -encoders | grep libx264  # is H.264 encoding available?\nffmpeg -encoders | grep libvpx   # is VP9 encoding available?', 'note': None}, {'repo': 'ffmpeg', 'slug': 'convert-anything-to-mp4', 'title': 'How to convert any video to MP4 (H.264 + AAC) — ffmpeg', 'scenario': 'You have a video in some odd format and need a file that plays everywhere: browsers, phones, editors.', 'code': 'ffmpeg -i input.avi -c:v libx264 -c:a aac output.mp4', 'note': None}, {'repo': 'ffmpeg', 'slug': 'convert-mp4-to-webm', 'title': 'How to convert MP4 to WebM (VP9 + Opus) — ffmpeg', 'scenario': 'You want smaller files for the web — for video tags and HTML5 players.', 'code': 'ffmpeg -i input.mp4 -c:v libvpx-vp9 -b:v 2M -c:a libopus output.webm', 'note': None}, {'repo': 'ffmpeg', 'slug': 'remux-mkv-to-mp4-no-reencode', 'title': 'How to convert MKV to MP4 without re-encoding — ffmpeg remux', 'scenario': 'The video itself is fine, only the container is wrong — swapping it takes seconds and loses zero quality.', 'code': 'ffmpeg -i input.mkv -c copy output.mp4\n# -c copy = copy streams as-is, no re-encoding', 'note': None}, {'repo': 'ffmpeg', 'slug': 'compress-video-crf', 'title': 'How to compress a video with FFmpeg — CRF explained', 'scenario': 'Your video file is too big to upload or send, and you want one number that controls the quality/size trade-off.', 'code': 'ffmpeg -i input.mp4 -c:v libx264 -crf 23 -preset medium -c:a aac -b:a 128k output.mp4\n# try -crf 28 for much smaller files, -crf 18 when quality matters most', 'note': 'CRF 18-28 is the useful range: lower means better quality and a bigger file; 23 is the default sweet spot.'}, {'repo': 'ffmpeg', 'slug': 'encoding-presets-speed-vs-size', 'title': 'FFmpeg presets: trade encoding speed for file size', 'scenario': 'Same quality, smaller file — if you can wait. Or a fast encode when you are in a hurry.', 'code': 'ffmpeg -i input.mp4 -c:v libx264 -crf 23 -preset slow output.mp4\n# presets: ultrafast superfast veryfast faster fast medium slow slower veryslow', 'note': None}, {'repo': 'ffmpeg', 'slug': 'two-pass-encoding-target-size', 'title': 'How to encode a video to an exact file size — two-pass FFmpeg', 'scenario': 'The file must be exactly X MB — for example an upload limit — and a single pass cannot promise that.', 'code': 'ffmpeg -y -i input.mp4 -c:v libx264 -b:v 1M -pass 1 -an -f null /dev/null && \\\nffmpeg -i input.mp4 -c:v libx264 -b:v 1M -pass 2 -c:a aac -b:a 128k output.mp4\n# -an = no audio on pass 1; /dev/null discards the first-pass output', 'note': '-an drops audio on pass 1; the first-pass output goes to /dev/null, only the statistics matter.'}, {'repo': 'ffmpeg', 'slug': 'extract-audio-mp3', 'title': 'How to extract audio from a video as MP3 — ffmpeg', 'scenario': 'You need just the soundtrack of a video — a song, a lecture, a voice memo.', 'code': 'ffmpeg -i input.mp4 -vn -c:a libmp3lame -q:a 2 audio.mp3\n# -vn = no video; -q:a 2 = high VBR quality (0 best … 9 worst)', 'note': None}, {'repo': 'ffmpeg', 'slug': 'extract-audio-m4a', 'title': 'How to extract audio from a video as M4A (AAC) — ffmpeg', 'scenario': 'Same job as MP3, but AAC gives better quality per megabyte and plays natively on Apple devices.', 'code': 'ffmpeg -i input.mp4 -vn -c:a aac -b:a 192k audio.m4a', 'note': None}, {'repo': 'ffmpeg', 'slug': 'extract-audio-without-reencoding', 'title': 'How to extract audio without re-encoding — ffmpeg -c:a copy', 'scenario': 'The fastest option — but it only works if the audio codec already fits the target container.', 'code': 'ffmpeg -i input.mp4 -vn -c:a copy audio.aac', 'note': None}, {'repo': 'ffmpeg', 'slug': 'video-to-gif-with-palette', 'title': 'How to turn a video into a good-looking GIF — the ffmpeg palette trick', 'scenario': 'A plain conversion makes banded, ugly GIFs; a custom palette is what makes them look clean and stay small.', 'code': 'ffmpeg -i input.mp4 -vf "fps=10,scale=480:-1:flags=lanczos,palettegen" palette.png\nffmpeg -i input.mp4 -i palette.png -filter_complex "fps=10,scale=480:-1:flags=lanczos[x];[x][1:v]paletteuse" output.gif\n# fps=10 keeps the GIF small; raise it (e.g. 15) for smoother motion', 'note': 'Two steps, same input: generate the palette first, then render with it. fps=10 keeps the GIF small; raise it (e.g. 15) for smoother motion.'}, {'repo': 'ffmpeg', 'slug': 'cut-video-fast-seek', 'title': 'How to cut a clip out of a video, fast — ffmpeg -ss before -i', 'scenario': 'You need 30 seconds out of a long video and do not want to re-encode anything.', 'code': 'ffmpeg -ss 00:01:30 -i input.mp4 -t 00:00:30 -c copy clip.mp4\n# -ss before -i = fast seek; -t = duration of the clip', 'note': None}, {'repo': 'ffmpeg', 'slug': 'cut-video-frame-accurate', 'title': 'How to cut a video frame-accurately — ffmpeg -ss after -i', 'scenario': 'The cut point must land on the exact frame, and the fast seek keeps missing it.', 'code': 'ffmpeg -i input.mp4 -ss 00:01:30 -t 00:00:30 -c:v libx264 -c:a aac clip.mp4\n# slower (decodes from the start) but frame-accurate', 'note': None}, {'repo': 'ffmpeg', 'slug': 'join-videos-concat', 'title': 'How to join videos without re-encoding — ffmpeg concat', 'scenario': 'You have several clips that belong together, and all of them share the same codec and parameters.', 'code': "# list.txt contains one line per file:\n#   file 'a.mp4'\n#   file 'b.mp4'\nffmpeg -f concat -safe 0 -i list.txt -c copy joined.mp4", 'note': None}, {'repo': 'ffmpeg', 'slug': 'scale-video-to-720p', 'title': 'How to resize a video to 720p — ffmpeg scale filter', 'scenario': 'You need the output at exactly 1280x720.', 'code': 'ffmpeg -i input.mp4 -vf "scale=1280:720" -c:a copy output.mp4', 'note': None}, {'repo': 'ffmpeg', 'slug': 'scale-video-by-width', 'title': 'How to resize a video by width and keep the aspect ratio — ffmpeg', 'scenario': 'You know the width you want; the height should follow the original aspect ratio automatically.', 'code': 'ffmpeg -i input.mp4 -vf "scale=640:-2" output.mp4', 'note': '-2 auto-computes the height and rounds it to an even number — H.264 requires even dimensions.'}, {'repo': 'ffmpeg', 'slug': 'crop-video-region', 'title': 'How to crop a region out of a video — ffmpeg crop', 'scenario': "Only a rectangle of the frame matters — a screen area, a speaker's face, a detail.", 'code': 'ffmpeg -i input.mp4 -vf "crop=640:480:100:50" output.mp4', 'note': 'Format is crop=W:H:X:Y — width, height, and the top-left corner to start from.'}, {'repo': 'ffmpeg', 'slug': 'add-watermark-overlay', 'title': 'How to put a watermark on a video — ffmpeg overlay', 'scenario': 'You want your logo burned into a corner of the video.', 'code': 'ffmpeg -i input.mp4 -i logo.png -filter_complex "overlay=W-w-10:10" -c:a copy output.mp4\n# W-w-10:10 = 10px margin from the top-right corner', 'note': 'W-w-10:10 positions the overlay 10px from the top-right corner.'}, {'repo': 'ffmpeg', 'slug': 'burn-subtitles-into-video', 'title': 'How to burn subtitles into a video — ffmpeg subtitles filter', 'scenario': 'Soft subtitles disappear on some players; hardcoded ones show everywhere.', 'code': 'ffmpeg -i input.mp4 -vf "subtitles=subs.srt" -c:a copy output.mp4\n# needs a build with libass; quote the path if it contains spaces or special chars', 'note': 'This needs an ffmpeg build with libass; quote the path if it contains spaces or special characters.'}, {'repo': 'ffmpeg', 'slug': 'drawtext-overlay', 'title': 'How to add text to a video without extra files — ffmpeg drawtext', 'scenario': 'A title, a timestamp, a label — plain text straight onto the frames.', 'code': 'ffmpeg -i input.mp4 -vf "drawtext=text=\'Hello\':fontsize=48:fontcolor=white:x=10:y=10" -c:a copy output.mp4', 'note': None}, {'repo': 'ffmpeg', 'slug': 'extract-poster-frame', 'title': 'How to grab a thumbnail frame from a video — ffmpeg', 'scenario': 'You need one still image — a poster or thumbnail — from a specific moment in the video.', 'code': 'ffmpeg -ss 00:00:05 -i input.mp4 -vframes 1 poster.jpg\n# -ss before -i = fast seek to that timestamp', 'note': None}, {'repo': 'ffmpeg', 'slug': 'dump-frames-as-images', 'title': 'How to export video frames as images — ffmpeg fps filter', 'scenario': 'You want one JPEG per second — for analysis, previews, or building a dataset.', 'code': 'ffmpeg -i input.mp4 -vf fps=1 frame_%03d.jpg\n# produces frame_001.jpg, frame_002.jpg … ; use fps=1/60 for one frame per minute', 'note': 'Use fps=1/60 for one frame per minute instead.'}, {'repo': 'ffmpeg', 'slug': 'replace-audio-track', 'title': "How to replace a video's audio track — ffmpeg -map", 'scenario': 'The picture is right but the sound is wrong: new music, a fixed voice-over, a different language.', 'code': 'ffmpeg -i video.mp4 -i new_audio.mp3 -c:v copy -c:a aac -map 0:v:0 -map 1:a:0 -shortest output.mp4\n# -map picks streams explicitly; -shortest ends output at the shorter input', 'note': '-map picks the streams explicitly; -shortest ends the output at the shorter input.'}, {'repo': 'ffmpeg', 'slug': 'stream-file-to-rtmp', 'title': 'How to stream a file to YouTube Live or Twitch — ffmpeg RTMP', 'scenario': 'You want to push a file (or loop it) to an RTMP endpoint.', 'code': 'ffmpeg -re -i input.mp4 -c:v libx264 -preset veryfast -b:v 2500k -c:a aac -b:a 128k -f flv rtmp://live.example.com/app/STREAM_KEY\n# -re reads input at native frame rate; replace the URL and key with yours', 'note': '-re reads the input at its native frame rate — without it you would blast the whole file at the server at once. Replace the URL and stream key with yours.'}, {'repo': 'ffmpeg', 'slug': 'batch-convert-folder', 'title': 'How to batch-convert a folder of videos — ffmpeg shell loops', 'scenario': 'Not one file but fifty: convert every MP4 in a folder to WebM, or pull an MP3 out of each one.', 'code': 'for f in *.mp4; do ffmpeg -i "$f" -c:v libvpx-vp9 -b:v 2M -c:a libopus "${f%.mp4}.webm"; done\nfor f in *.mp4; do ffmpeg -i "$f" -vn -c:a libmp3lame -q:a 2 "${f%.mp4}.mp3"; done', 'note': None}, {'repo': 'docker', 'slug': 'pull-image', 'title': 'How to download a Docker image — docker pull', 'scenario': 'You need an image on your machine before anything can run.', 'code': "docker pull nginx:1.27        # pin a version (don't use :latest in production)", 'note': "Pin a version — don't use :latest in production."}, {'repo': 'docker', 'slug': 'list-images', 'title': 'How to list Docker images on your machine — docker images', 'scenario': 'You want to see which images you have, their tags, sizes and ages.', 'code': 'docker images                 # REPOSITORY, TAG, size, age', 'note': None}, {'repo': 'docker', 'slug': 'build-image-from-dockerfile', 'title': 'How to build a Docker image from a Dockerfile — docker build', 'scenario': 'You have a Dockerfile and want it turned into a named, runnable image.', 'code': 'docker build -t myapp:1.0 .          # -t names it; "." is the build context', 'note': '-t names the image; the dot is the build context — the directory Docker can see.'}, {'repo': 'docker', 'slug': 'tag-and-push-image', 'title': 'How to tag and push a Docker image to a registry', 'scenario': 'Your image works locally and now needs to live in a registry where servers (or teammates) can pull it.', 'code': 'docker tag myapp:1.0 myregistry.com/team/myapp:1.0\ndocker login && docker push myregistry.com/team/myapp:1.0', 'note': None}, {'repo': 'docker', 'slug': 'remove-images-and-prune', 'title': 'How to delete Docker images and reclaim disk — rmi and image prune', 'scenario': 'Old images are eating your disk and you want the unused ones gone.', 'code': 'docker rmi myapp:1.0          # fails if a container still uses it; -f to force\ndocker image prune            # dangling only (safe)\ndocker image prune -a         # ALL unused — re-downloads hurt on slow networks', 'note': None}, {'repo': 'docker', 'slug': 'run-container', 'title': 'How to run a Docker container — docker run with ports and volumes', 'scenario': 'The one command that starts most containers: detached, named, with a port published and data kept in a volume.', 'code': 'docker run -d --name web -p 8080:80 -v webdata:/usr/share/nginx/html nginx:1.27\n# -d detached, --name easy handle, -p host:container, -v volume:mount', 'note': '-d runs it detached, --name gives you an easy handle, -p maps host:container ports, -v mounts a volume.'}, {'repo': 'docker', 'slug': 'list-containers', 'title': 'How to list Docker containers — docker ps and ps -a', 'scenario': 'You need to see what is running — or everything that exists, including the dead ones.', 'code': 'docker ps       # running only\ndocker ps -a    # everything, including dead ones', 'note': None}, {'repo': 'docker', 'slug': 'start-stop-restart-container', 'title': 'How to start, stop and restart a Docker container', 'scenario': 'The container exists already; you just need it stopped, started, or bounced.', 'code': 'docker stop web && docker start web    # or: docker restart web', 'note': None}, {'repo': 'docker', 'slug': 'remove-container', 'title': 'How to delete a Docker container — docker rm', 'scenario': 'A container is done for good and should disappear.', 'code': 'docker rm web       # stopped only\ndocker rm -f web    # stop AND delete, right now', 'note': 'Plain rm only works on stopped containers; -f stops and deletes in one go.'}, {'repo': 'docker', 'slug': 'throwaway-container-run-rm', 'title': 'How to run a throwaway Docker container — docker run --rm', 'scenario': 'You want to poke around inside an image and leave nothing behind when you exit.', 'code': 'docker run --rm -it ubuntu:24.04 bash   # gone when you exit — great for experiments', 'note': None}, {'repo': 'docker', 'slug': 'exec-shell-in-running-container', 'title': 'How to open a shell inside a running container — docker exec -it', 'scenario': 'The container is running but something inside it needs a look.', 'code': 'docker exec -it web sh    # sh exists everywhere; try bash if it fails', 'note': 'sh exists almost everywhere; try bash if it fails.'}, {'repo': 'docker', 'slug': 'container-logs-follow-tail', 'title': "How to read a container's logs — docker logs -f --tail", 'scenario': 'The app misbehaves and its output is the first place to look — live, but only the recent part.', 'code': 'docker logs -f --tail 100 web   # follow live, last 100 lines', 'note': None}, {'repo': 'docker', 'slug': 'copy-files-with-docker-cp', 'title': 'How to copy files in and out of a container — docker cp', 'scenario': 'A config file needs to come out for inspection, or a fixed file needs to go in.', 'code': 'docker cp web:/etc/nginx/nginx.conf ./      # container -> host\ndocker cp ./index.html web:/usr/share/nginx/html/  # host -> container', 'note': None}, {'repo': 'docker', 'slug': 'volumes-persistent-data', 'title': 'How to keep data in Docker volumes — create, list, delete', 'scenario': 'Containers get deleted; your data must not. Named volumes survive container deletion.', 'code': 'docker volume create webdata    # named volume (survives container deletion)\ndocker volume ls                # list them\ndocker volume rm webdata        # ⚠️ deletes the data — double-check the name', 'note': 'Deleting a volume deletes the data in it — double-check the name first.'}, {'repo': 'docker', 'slug': 'container-networks', 'title': 'How to connect containers on a Docker network', 'scenario': 'Two containers need to talk to each other by name instead of by IP.', 'code': "docker network create mynet                       # containers on mynet resolve each other by name\ndocker run -d --name api --network mynet myapp:1.0\ndocker network inspect mynet                      # see who's attached", 'note': None}, {'repo': 'docker', 'slug': 'dockerfile-essential-instructions', 'title': 'The Dockerfile instructions that matter — FROM, WORKDIR, COPY, RUN, EXPOSE, CMD', 'scenario': 'You are writing a Dockerfile and want the essential instructions in the order they are usually layered.', 'code': 'FROM node:22-alpine        # base image — always pin a version\nWORKDIR /app               # following paths are relative to /app\nCOPY package*.json ./      # manifests first (better layer caching)\nRUN npm ci --omit=dev      # install deps at build time\nCOPY . .                   # then the source\nEXPOSE 3000                # documents the port (does NOT publish it)\nCMD ["node", "server.js"]  # default command; ENTRYPOINT + CMD = fixed binary + default args', 'note': 'Copy the dependency manifests before the source — that ordering is what makes layer caching work for you. EXPOSE documents the port; it does not publish it.'}, {'repo': 'docker', 'slug': 'dockerfile-minimal-working-example', 'title': 'A minimal working Dockerfile — a Python app, built and run', 'scenario': 'You want one complete, small example you can copy and adapt: image definition, build, run.', 'code': 'FROM python:3.12-slim\nWORKDIR /app\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY . .\nEXPOSE 8000\nCMD ["python", "app.py"]\ndocker build -t hello-py:1.0 . && docker run -d --name hello-py -p 8000:8000 hello-py:1.0', 'note': None}, {'repo': 'docker', 'slug': 'compose-up-and-down', 'title': 'How to start and stop a multi-container app — docker compose up and down', 'scenario': 'Your app is more than one container and they should start and stop as one unit.', 'code': 'docker compose up -d        # build (if needed) + start everything, detached\ndocker compose down         # stop + remove containers/networks (volumes stay)\ndocker compose down -v      # also delete named volumes — ⚠️ data loss', 'note': 'down removes containers and networks but keeps named volumes; down -v deletes the volumes too — that is data loss.'}, {'repo': 'docker', 'slug': 'compose-operate-the-stack', 'title': 'How to operate a running Compose stack — ps, logs, exec', 'scenario': "The stack is up and you need its status, one service's logs, or a command inside the database service.", 'code': 'docker compose ps                               # status of every service\ndocker compose logs -f web                      # follow one service\ndocker compose exec db psql -U postgres         # run a command in the db service', 'note': None}, {'repo': 'docker', 'slug': 'compose-sample-web-and-database', 'title': 'Sample compose.yaml — a web service with a Postgres database', 'scenario': 'You want a realistic starting point: an app service wired to a database with persistent storage.', 'code': 'services:\n  web:\n    build: .\n    ports: ["3000:3000"]\n    depends_on: [db]\n  db:\n    image: postgres:16\n    environment: {POSTGRES_PASSWORD: example}\n    volumes: [pgdata:/var/lib/postgresql/data]\nvolumes: {pgdata:}', 'note': None}, {'repo': 'docker', 'slug': 'system-prune-cleanup', 'title': 'How to clean up everything unused in Docker — docker system prune', 'scenario': 'Disk is full and you want stopped containers, unused networks and unused images gone in one sweep.', 'code': 'docker system prune                # stopped containers, unused networks/images (asks first)\ndocker system prune -a --volumes   # ⚠️ EVERYTHING unused — read twice, run once', 'note': 'The -a --volumes form removes EVERYTHING unused — read it twice, run it once.'}, {'repo': 'docker', 'slug': 'container-prune', 'title': 'How to remove only stopped containers — docker container prune', 'scenario': 'You want the dead containers gone but images and running containers untouched.', 'code': 'docker container prune        # safe-ish: running containers are untouched', 'note': None}, {'repo': 'docker', 'slug': 'inspect-container-state', 'title': 'How to inspect a Docker object — docker inspect', 'scenario': 'You need the full truth about a container: state, exit code, mounts, environment.', 'code': "docker inspect -f '{{.State.Status}}' web   # running / exited / dead", 'note': "The -f form pulls out a single field — here the container's status — which is what makes inspect script-friendly."}, {'repo': 'docker', 'slug': 'stats-and-top', 'title': 'How to see what a container is doing — docker stats and docker top', 'scenario': 'Something is slow or a container looks hung: check its resource usage and whether your app is actually running inside.', 'code': 'docker stats --no-stream       # one snapshot (script-friendly); drop the flag for live view\ndocker top web                # is your app actually running in there?', 'note': None}, {'repo': 'docker', 'slug': 'container-wont-start-drill', 'title': "Container won't start? The three-step Docker drill", 'scenario': 'A container exits immediately or never comes up, and you need a method, not random poking.', 'code': 'docker logs web               # 1. read the error — 90% of answers are here\ndocker inspect web            # 2. check State.ExitCode, mounts, and env\ndocker run --rm -it --entrypoint sh myapp:1.0   # 3. bypass CMD, explore the image yourself', 'note': 'Logs first — most answers are there; then inspect for state, exit code, mounts and env; then bypass the CMD with an entrypoint shell and explore the image yourself.'}, {'repo': 'curl', 'slug': 'simple-get-request', 'title': 'How to make a GET request with curl', 'scenario': 'The default move: fetch a URL and print the response body.', 'code': 'curl https://api.example.com/users', 'note': None}, {'repo': 'curl', 'slug': 'post-json', 'title': 'How to POST JSON with curl', 'scenario': 'You are creating something through an API and the body has to be JSON.', 'code': 'curl -X POST https://api.example.com/users \\\n  -H "Content-Type: application/json" \\\n  -d \'{"name":"ezra","role":"engineer"}\'', 'note': '-X sets the method, -H sets headers, -d sends the body — and -d already implies POST.'}, {'repo': 'curl', 'slug': 'put-replace-resource', 'title': 'How to replace a resource with curl — PUT', 'scenario': 'The whole resource at that URL gets replaced by what you send.', 'code': 'curl -X PUT https://api.example.com/users/1 \\\n  -H "Content-Type: application/json" \\\n  -d \'{"name":"ezra","role":"senior engineer"}\'', 'note': None}, {'repo': 'curl', 'slug': 'delete-resource', 'title': 'How to delete a resource with curl — DELETE', 'scenario': 'One call, and the resource at that URL is gone.', 'code': 'curl -X DELETE https://api.example.com/users/1', 'note': None}, {'repo': 'curl', 'slug': 'patch-partial-update', 'title': 'How to partially update a resource with curl — PATCH', 'scenario': 'Only one field changed — send just that field instead of the whole object.', 'code': 'curl -X PATCH https://api.example.com/users/1 \\\n  -H "Content-Type: application/json" \\\n  -d \'{"email":"new@example.com"}\'', 'note': None}, {'repo': 'curl', 'slug': 'head-request-headers-only', 'title': "How to check a URL's headers without downloading the body — curl -I", 'scenario': 'You want to know a URL exists and read its headers, without pulling the body down.', 'code': 'curl -I https://example.com', 'note': None}, {'repo': 'curl', 'slug': 'custom-headers', 'title': 'How to send custom headers with curl — -H', 'scenario': 'The API wants an API key or a specific Accept header.', 'code': 'curl -H "X-API-Key: abc123" -H "Accept: application/json" \\\n  https://api.example.com/data', 'note': 'Repeat -H once per header.'}, {'repo': 'curl', 'slug': 'bearer-token-auth', 'title': 'How to call an API with a Bearer token — curl Authorization header', 'scenario': 'The standard way to call APIs protected by OAuth2 or a JWT.', 'code': 'curl -H "Authorization: Bearer eyJhbGciOiJIUzI1NiJ9..." \\\n  https://api.example.com/me', 'note': None}, {'repo': 'curl', 'slug': 'basic-auth', 'title': 'How to use Basic auth with curl — -u', 'scenario': 'The endpoint wants a username and password.', 'code': 'curl -u admin:s3cret https://api.example.com/secure\n# equivalent: -H "Authorization: Basic YWRtaW46czNjcmV0"', 'note': '-u builds the Authorization: Basic header for you — the commented line in the cheatsheet shows the equivalent header.'}, {'repo': 'curl', 'slug': 'custom-user-agent', 'title': 'How to set a custom User-Agent with curl — -A', 'scenario': 'Some servers and WAFs behave differently depending on the client string they see.', 'code': 'curl -A "MyApp/1.0 (contact: me@example.com)" https://example.com', 'note': None}, {'repo': 'curl', 'slug': 'post-form-data-urlencode', 'title': 'How to POST form data with curl — and let curl URL-encode it', 'scenario': 'Classic HTML-form style data — or values containing spaces and ampersands that must be encoded safely first.', 'code': 'curl -d "name=ezra&plan=pro" https://example.com/signup\ncurl --data-urlencode "q=hello world & more" https://example.com/search', 'note': '--data-urlencode encodes special characters (spaces, &, =) for you; plain -d sends the string as-is.'}, {'repo': 'curl', 'slug': 'upload-file-multipart', 'title': 'How to upload a file with curl — -F multipart form', 'scenario': 'The endpoint expects a multipart/form-data upload, like a browser file form.', 'code': 'curl -F "avatar=@me.png" -F "bio=hello world" https://example.com/upload\n# add ;type=image/png after the filename to set the MIME type explicitly', 'note': '@ reads the file from disk; add ;type=image/png after the filename to set the MIME type explicitly.'}, {'repo': 'curl', 'slug': 'show-response-headers', 'title': 'How to see response headers with curl — -i', 'scenario': 'Status and headers matter as much as the body when you are debugging an API.', 'code': 'curl -i https://example.com', 'note': None}, {'repo': 'curl', 'slug': 'save-response-to-file', 'title': 'How to save curl output to a file — -o vs -O', 'scenario': 'The response should land on disk — under a name you choose, or under the name the URL already has.', 'code': 'curl -o page.html https://example.com\ncurl -O https://example.com/files/report.pdf   # saves as report.pdf', 'note': 'Lowercase -o takes your filename; uppercase -O reuses the last part of the URL.'}, {'repo': 'curl', 'slug': 'silent-mode-show-errors', 'title': "How to silence curl's progress bar but keep the errors — -sS", 'scenario': 'In scripts, the progress meter is noise — but real errors must still print.', 'code': 'curl -sS https://api.example.com/data', 'note': '-s hides the progress bar; -S makes sure errors still show.'}, {'repo': 'curl', 'slug': 'measure-timing-and-status-code', 'title': 'How to measure response time and status code with curl — -w', 'scenario': 'Is it slow, and where does the time go? Get the status code and timings in one line.', 'code': 'curl -s -o /dev/null -w "code=%{http_code} time=%{time_total}s size=%{size_download}\\n" \\\n  https://example.com\n# more variables: %{time_connect} %{speed_download} %{url_effective}', 'note': 'More variables exist: %{time_connect}, %{speed_download}, %{url_effective} — and -o /dev/null discards the body so it cannot skew the measurement.'}, {'repo': 'curl', 'slug': 'verbose-mode', 'title': 'How to see the whole HTTP conversation — curl -v', 'scenario': 'Something is off and you need the request headers, the response headers, and the TLS handshake.', 'code': 'curl -v https://example.com', 'note': None}, {'repo': 'curl', 'slug': 'trace-ascii-full-dump', 'title': 'How to get a full curl trace — --trace-ascii', 'scenario': 'Verbose is not enough: you need everything, including connection internals.', 'code': 'curl --trace-ascii - https://example.com 2>&1 | head -40', 'note': 'The dash means stdout; piping through head keeps the dump readable.'}, {'repo': 'curl', 'slug': 'which-http-version', 'title': 'How to check which HTTP version curl negotiated — %{http_version}', 'scenario': 'You expected HTTP/2 and want proof of what was actually negotiated.', 'code': 'curl -s -o /dev/null -w "HTTP version: %{http_version}\\n" https://example.com\n# force one: curl --http2 https://example.com', 'note': None}, {'repo': 'curl', 'slug': 'skip-tls-verification-debug', 'title': 'How to skip TLS certificate checks with curl — -k (debug only)', 'scenario': 'A dev server with a self-signed certificate refuses your request.', 'code': 'curl -k https://self-signed.example.com   # ⚠️ debug only, never in scripts that matter', 'note': 'Debug only. -k disables MITM protection — never use it in production or in scripts that matter.'}, {'repo': 'curl', 'slug': 'resume-interrupted-download', 'title': 'How to resume an interrupted download with curl — -C -', 'scenario': 'A big download died halfway and starting over would waste what you already have.', 'code': 'curl -C - -O https://example.com/big.iso', 'note': '-C - auto-detects how much you already have and continues from there.'}, {'repo': 'curl', 'slug': 'limit-download-speed', 'title': "How to limit curl's download speed — --limit-rate", 'scenario': 'You are on a shared server or a metered connection and a full-speed download would be rude.', 'code': 'curl --limit-rate 500K -O https://example.com/big.iso', 'note': '--limit-rate accepts K, M and G suffixes.'}, {'repo': 'curl', 'slug': 'retry-failed-downloads', 'title': 'How to make curl retry failed downloads — --retry', 'scenario': 'The server is flaky and transient failures should not kill your script.', 'code': 'curl --retry 5 --retry-delay 3 -O https://example.com/file.zip', 'note': None}, {'repo': 'curl', 'slug': 'cookies-and-sessions', 'title': 'How to log in once and reuse the session with curl — cookie jars', 'scenario': 'The site needs a login before the interesting pages work: save the cookies after logging in, then send them with every later request.', 'code': 'curl -c cookies.txt -d "user=ezra&pass=s3cret" https://example.com/login\ncurl -b cookies.txt https://example.com/dashboard\n# -b "name=value" also works for a one-off cookie without a file', 'note': '-c writes the cookie jar after the request; -b reads it back. A one-off -b "name=value" also works without a file.'}, {'repo': 'curl', 'slug': 'route-through-proxy', 'title': 'How to route curl through a proxy — HTTP and SOCKS5', 'scenario': 'Your traffic has to leave through a proxy — a company gateway, or a local SSH tunnel.', 'code': 'curl -x http://proxy.example.com:8080 https://example.com\n# with auth: -x http://user:pass@proxy.example.com:8080\ncurl -x socks5://127.0.0.1:1080 https://example.com', 'note': 'With auth the HTTP form is -x http://user:pass@proxy.example.com:8080; the SOCKS5 form is the classic companion to an ssh -D tunnel.'}, {'repo': 'jq', 'slug': 'pretty-print-json', 'title': 'How to pretty-print JSON with jq', 'scenario': 'Someone handed you a one-line JSON blob and you need to actually read it.', 'code': 'jq \'.\' config.json\n# input:  {"name":"api-server","port":8080}\n# output: {\n#           "name": "api-server",\n#           "port": 8080\n#         }', 'note': None}, {'repo': 'jq', 'slug': 'extract-one-field', 'title': 'How to extract one field from JSON with jq', 'scenario': 'You need a single value out of an object — and strings come back quoted, which is normal JSON.', 'code': 'jq \'.name\' config.json\n# input:  {"name":"api-server","port":8080}\n# output: "api-server"', 'note': None}, {'repo': 'jq', 'slug': 'raw-output-no-quotes', 'title': 'How to get strings without quotes from jq — -r raw output', 'scenario': 'The result feeds into another shell command, where JSON quotes would only get in the way.', 'code': "jq -r '.name' config.json\n# output: api-server", 'note': None}, {'repo': 'jq', 'slug': 'compact-output-one-per-line', 'title': 'How to print one JSON object per line with jq — -c', 'scenario': 'Log pipelines and line-oriented tools want compact output: one object, one line.', 'code': 'jq -c \'.users\' config.json\n# output: [{"name":"ana","age":28},{"name":"bruno","age":17},{"name":"carla","age":34}]', 'note': None}, {'repo': 'jq', 'slug': 'drill-into-nested-objects', 'title': 'How to drill into nested JSON objects with jq', 'scenario': 'The value you want is buried a few objects deep.', 'code': 'jq \'.owner.email\' config.json\n# input:  {"owner":{"name":"Ezra","email":"ezra@example.com"}}\n# output: "ezra@example.com"', 'note': None}, {'repo': 'jq', 'slug': 'index-and-stream-arrays', 'title': 'How to index into and stream JSON arrays with jq', 'scenario': 'You need the first element, the last one — or every element, one by one.', 'code': 'jq \'.users[0].name\' config.json   # first user\'s name  -> "ana"\njq \'.users[-1].name\' config.json  # last user\'s name   -> "carla"\njq -r \'.users[].name\' config.json\n# output: ana\n#         bruno\n#         carla', 'note': None}, {'repo': 'jq', 'slug': 'count-with-length', 'title': 'How to count things in JSON with jq — length', 'scenario': 'How many users are in the array? How long is that string? How many keys does the object have?', 'code': 'jq \'.users | length\' config.json   # -> 3\njq \'.name | length\' config.json    # -> 10  (characters in "api-server")', 'note': None}, {'repo': 'jq', 'slug': 'select-by-number', 'title': 'How to filter JSON rows by a number with jq select', 'scenario': 'Keep only the rows where a number passes your test — here, the adults.', 'code': "jq -r '.users[] | select(.age >= 18) | .name' config.json\n# output: ana\n#         carla        (bruno is 17, filtered out)", 'note': None}, {'repo': 'jq', 'slug': 'select-by-string-match', 'title': 'How to filter JSON by exact string match with jq select', 'scenario': 'Only the admins, please — string comparison with ==, quotes included.', 'code': 'jq -r \'.users[] | select(.role == "admin") | .name\' config.json\n# output: ana', 'note': None}, {'repo': 'jq', 'slug': 'select-with-boolean-logic', 'title': 'How to combine conditions in jq — and, or, not', 'scenario': 'One condition is not enough: you need rows that pass several tests, or fail one.', 'code': "jq -r '.users[] | select(.age > 18 and .active) | .name' config.json\n# output: ana        (carla is inactive, bruno is 17)\njq -r '.users[] | select(.active | not) | .name' config.json\n# output: carla", 'note': None}, {'repo': 'jq', 'slug': 'map-pluck-one-field', 'title': 'How to pluck one field from every element with jq map', 'scenario': 'You have an array of objects and need an array of just their names.', 'code': 'jq \'.users | map(.name)\' config.json\n# output: ["ana","bruno","carla"]', 'note': None}, {'repo': 'jq', 'slug': 'map-reshape-objects', 'title': 'How to keep only some fields of every object with jq map', 'scenario': 'The objects carry more than you need downstream — trim each one to the fields that matter.', 'code': 'jq -c \'.users | map({name, city})\' config.json\n# output: [{"name":"ana","city":"madrid"},{"name":"bruno","city":"lisboa"},{"name":"carla","city":"madrid"}]', 'note': None}, {'repo': 'jq', 'slug': 'map-add-computed-field', 'title': 'How to add a computed field to every JSON object with jq', 'scenario': 'Each object needs a new field derived from its own data — without changing the originals.', 'code': 'jq -c \'.users | map(. + {senior: (.age >= 30)}) | .[2]\' config.json\n# output: {"name":"carla","age":34,"role":"user","active":false,"city":"madrid","score":88,"senior":true}', 'note': None}, {'repo': 'jq', 'slug': 'chain-filters-with-pipes', 'title': 'How to chain jq filters with pipes', 'scenario': "Filter first, then reshape: the pipe feeds one filter's output into the next, and you compose freely.", 'code': 'jq -c \'.users | map(select(.active)) | map(.name)\' config.json\n# output: ["ana","bruno"]      (filter first, then pluck)', 'note': None}, {'repo': 'jq', 'slug': 'build-new-objects', 'title': 'How to build new JSON objects with jq', 'scenario': 'You need a smaller object picked from one place — or a summary assembled from many places at once.', 'code': 'jq \'.users[0] | {name, age}\' config.json\n# output: { "name": "ana", "age": 28 }\njq \'. | {app: .name, owner_email: .owner.email, user_count: (.users | length)}\' config.json\n# output: { "app": "api-server", "owner_email": "ezra@example.com", "user_count": 3 }', 'note': None}, {'repo': 'jq', 'slug': 'strings-and-type-conversion', 'title': 'How to convert types and split or join strings with jq', 'scenario': 'The API is inconsistent: ages arrive as numbers but you need strings — or a comma-joined string needs to become an array.', 'code': 'jq \'.users | map(.age | tostring)\' config.json\n# output: ["28","17","34"]\necho \'"42"\' | jq \'tonumber + 8\'\n# output: 50\necho \'"a,b,c"\' | jq \'split(",")\'        # -> ["a","b","c"]\njq -n -r \'["a","b","c"] | join("; ")\'   # -n = null input; -> a; b; c', 'note': "tostring and tonumber normalize a field's type before comparing or concatenating; split and join convert between strings and arrays."}, {'repo': 'jq', 'slug': 'regex-match-with-test', 'title': 'How to match strings with a regex inside jq — test()', 'scenario': 'Keep the rows whose name matches a pattern — here, names starting with a.', 'code': 'jq -r \'.users[] | select(.name | test("^a")) | .name\' config.json\n# output: ana        (names starting with "a")', 'note': None}, {'repo': 'jq', 'slug': 'sort-by-field', 'title': 'How to sort JSON objects by a field with jq — sort_by', 'scenario': 'The array is in arrival order and you need it ordered by age.', 'code': 'jq \'.users | sort_by(.age) | map(.name)\' config.json\n# output: ["bruno","ana","carla"]      (17, 28, 34)', 'note': None}, {'repo': 'jq', 'slug': 'deduplicate-with-unique', 'title': 'How to deduplicate values with jq — unique', 'scenario': 'The same city appears three times and you want each value once.', 'code': 'jq \'.users | map(.city) | unique\' config.json\n# output: ["lisboa","madrid"]', 'note': 'unique sorts as it deduplicates — feed it a plucked array of the field you care about.'}, {'repo': 'jq', 'slug': 'group-by-and-count', 'title': 'How to group and count JSON data with jq — group_by', 'scenario': 'How many users per city? Group the rows, then count each group.', 'code': 'jq -c \'.users | group_by(.city) | map({city: .[0].city, count: length})\' config.json\n# output: [{"city":"lisboa","count":1},{"city":"madrid","count":2}]', 'note': None}, {'repo': 'jq', 'slug': 'sum-with-add', 'title': 'How to sum numbers in JSON with jq — add', 'scenario': 'A column of scores needs a total.', 'code': "jq '.users | map(.score) | add' config.json\n# output: 255      (92 + 75 + 88)", 'note': 'add also concatenates arrays and merges objects — here it sums 92 + 75 + 88 = 255.'}, {'repo': 'jq', 'slug': 'max-min-by-field', 'title': 'How to find the top or bottom object by a field with jq — max_by and min_by', 'scenario': 'Who scored highest? Who is youngest? You want the whole winning object, not just the value.', 'code': 'jq \'.users | max_by(.score) | {name, score}\' config.json\n# output: { "name": "ana", "score": 92 }\njq \'.users | min_by(.age) | {name, age}\' config.json\n# output: { "name": "bruno", "age": 17 }', 'note': None}, {'repo': 'jq', 'slug': 'keys-has-del', 'title': 'How to inspect and trim JSON object keys with jq — keys, has, del', 'scenario': 'You need to know what keys an object has, whether a specific one exists, or produce the object minus a field.', 'code': 'jq \'.users[0] | keys\' config.json\n# output: ["active","age","city","name","role","score"]\njq \'.users[0] | has("role")\' config.json   # -> true\njq -c \'del(.debug) | keys\' config.json\n# output: ["name","owner","port","tags","users","version"]   (debug gone)', 'note': None}, {'repo': 'jq', 'slug': 'real-world-api-and-logs', 'title': 'jq in the real world: shape API responses and count log levels', 'scenario': 'The two everyday jobs: fetch JSON from an API and shape it on the spot — or reduce a JSON log file to a count per level.', 'code': 'curl -s https://api.github.com/repos/jqlang/jq | jq \'{stars: .stargazers_count, forks: .forks_count}\'\n# output: { "stars": 21000, "forks": 1500 }\njq -r \'.level\' app.log | sort | uniq -c\n# output:   2 error\n#           2 info', 'note': None}, {'repo': 'jq', 'slug': 'shell-variables-and-slurp', 'title': 'How to pass shell variables into jq safely — --arg — and slurp many documents with -s', 'scenario': 'A version string from your script must land in the JSON without injection risk — and a stream of separate JSON documents needs to become one array, or one merged object.', 'code': 'jq --arg v "2.4.1" \'.version = $v\' config.json | jq \'.version\'\n# output: "2.4.1"\nprintf \'%s\\n\' \'{"a":1}\' \'{"b":2}\' | jq -s \'.\'\n# output: [ { "a": 1 }, { "b": 2 } ]\nprintf \'%s\\n\' \'{"a":1}\' \'{"b":2}\' | jq -s \'add\'\n# output: { "a": 1, "b": 2 }', 'note': 'Never interpolate $VAR into the filter string; --arg passes it as data. --slurp (-s) reads a stream of JSON values into an array; add then merges them.'}, {'repo': 'regex', 'slug': 'dot-any-character', 'title': 'What does . match in regex? Any character except a newline', 'scenario': 'You need a wildcard: one character, any character, in a known position.', 'code': 'a.c\n# matches: abc, a1c, a-c … but not "ac" or "a\\nc"', 'note': None}, {'repo': 'regex', 'slug': 'shorthand-classes-digit-word-space', 'title': 'Regex shorthands: \\d for digits, \\w for word characters, \\s for whitespace', 'scenario': 'Three shorthands cover most everyday matching: digits, word characters, and whitespace.', 'code': 'Order \\d+\n# matches "Order 42" — one or more digits\n\\w+\n# matches "user_1", "abc", "007" — stops at spaces and punctuation\nHello\\sWorld\n# matches "Hello World", "Hello\\tWorld"', 'note': '\\d is [0-9], \\w is [A-Za-z0-9_], and \\s covers space, tab and newline. The uppercase version always negates the lowercase one — the rule holds for \\D, \\W and \\S too.'}, {'repo': 'regex', 'slug': 'anchors-start-and-end', 'title': 'How to anchor a regex to the start or end — ^ and $', 'scenario': 'The match only counts at the very beginning or the very end of the string — or of each line, with the multiline flag.', 'code': '^Hello\n# matches only if the string/line starts with "Hello"\n\\d+$\n# matches only if the string/line ends with digits', 'note': None}, {'repo': 'regex', 'slug': 'word-boundary', 'title': 'How to match whole words only in regex — \\b word boundary', 'scenario': 'You want cat, but not cats, concat, or educate.', 'code': '\\bcat\\b\n# matches "cat" but not "cats", "concat", or "educate"', 'note': None}, {'repo': 'regex', 'slug': 'quantifiers-star-plus-question', 'title': 'Regex quantifiers * + ? — zero or more, one or more, optional', 'scenario': 'A character or group should repeat: any number of times, at least once, or not at all.', 'code': 'https?://\n# "http://" or "https://" — the s is optional\n\\d+\n# one or more digits: "5", "42", "007"\ncolou?r\n# "color" or "colour"', 'note': 'These are the three you will use most of the time.'}, {'repo': 'regex', 'slug': 'quantifier-exact-counts', 'title': 'How to repeat a pattern an exact number of times — {n}, {n,}, {n,m}', 'scenario': 'Star and plus are too vague: you need exactly 3 digits, at least 2, or between 4 and 8.', 'code': '\\d{3}-\\d{4}\n# "555-1234" — exactly 3 digits, dash, exactly 4 digits\n\\d{2,}\n# at least 2 digits\n[a-z]{4,8}\n# 4 to 8 lowercase letters (e.g. a username rule)', 'note': None}, {'repo': 'regex', 'slug': 'greedy-vs-lazy', 'title': 'Greedy vs lazy matching in regex — .* vs .*?', 'scenario': 'Your pattern matched way too much: it ran to the last possible end instead of stopping at the first.', 'code': '<.*>\n# greedy: on "<b>hi</b>" matches the whole "<b>hi</b>"\n<.*?>\n# lazy: on "<b>hi</b>" matches "<b>" then "</b>" separately', 'note': 'Quantifiers are greedy by default; adding ? makes them lazy. Possessive quantifiers (*+, ++) exist in PCRE/Java but not in Python or JavaScript.'}, {'repo': 'regex', 'slug': 'character-classes-and-negation', 'title': 'How to match one character from a set — [...] and [^...]', 'scenario': 'Any vowel, any letter — or any character that is NOT a digit: a set, or everything except a set.', 'code': '[aeiou]\n# any single vowel\n[a-zA-Z]\n# any single letter\ngr[ae]y\n# "gray" or "grey"\n[^0-9]\n# same as \\D — any non-digit\n[^<>]*\n# any run of characters that aren\'t angle brackets', 'note': "Inside a class most metacharacters lose their magic (. is literal), but ] \\ ^ and - still need care; a ^ only means 'not' when it is the first character inside the brackets."}, {'repo': 'regex', 'slug': 'alternation-or', 'title': 'How to match this or that in regex — | alternation', 'scenario': 'Two (or more) alternatives are equally acceptable and either one should match.', 'code': 'cat|dog\n# "cat" or "dog"\ngr(a|e)y\n# "gray" or "grey" — the | only applies inside the group', 'note': '| has the lowest precedence of all — wrap it in (...) to limit its scope, as gr(a|e)y does.'}, {'repo': 'regex', 'slug': 'capturing-groups', 'title': 'How to capture parts of a match — (...) groups', 'scenario': 'You do not just want a match: you want the pieces — area code here, number there — numbered from 1, left to right.', 'code': '(\\d{3})-(\\d{4})\n# group 1 = area code, group 2 = number\n(ha)+\n# "ha", "haha", "hahaha" — quantifier applies to the group', 'note': None}, {'repo': 'regex', 'slug': 'named-capturing-groups', 'title': 'How to name a capture group — (?<name>...)', 'scenario': 'Group $7 tells you nothing; a group named year explains itself.', 'code': '(?<year>\\d{4})-(?<month>\\d{2})\n# year="2026", month="10"', 'note': 'Python also accepts (?P<name>...); JavaScript needs ES2018+.'}, {'repo': 'regex', 'slug': 'non-capturing-groups', 'title': 'How to group without capturing — (?:...)', 'scenario': "You need grouping for a quantifier or an alternation, but the extra capture slot would shift everyone's numbers.", 'code': '(?:https?://)?[\\w.-]+\n# optional scheme, not captured — keeps group numbers clean', 'note': None}, {'repo': 'regex', 'slug': 'backreferences', 'title': 'How to match the same text twice — backreferences with \\1', 'scenario': 'The closing quote must equal the opening one; the repeated word must be the same word.', 'code': '([\'"]).*?\\1\n# "hello" or \'hello\' — closing quote must match the opening one\n(\\w+)\\s+\\1\n# repeated word: "the the"', 'note': None}, {'repo': 'regex', 'slug': 'lookahead-assertions', 'title': 'Lookahead in regex: require (or forbid) what follows — (?=...) and (?!...)', 'scenario': 'A match only counts if the next characters are — or are not — a specific thing, without consuming them.', 'code': '\\d+(?= dollars)\n# matches "100" in "100 dollars" — " dollars" stays for later\n^(?=.*[A-Z])(?=.*\\d).{8,}$\n# password: 8+ chars, at least one uppercase and one digit\nfoo(?!bar)\n# "foo" not followed by "bar" — matches "food", "fool", not "foobar"', 'note': None}, {'repo': 'regex', 'slug': 'lookbehind-assertions', 'title': 'Lookbehind in regex: require (or forbid) what precedes — (?<=...) and (?<!...)', 'scenario': "The number counts only when a dollar sign stands before it; the word only when 'not' does not.", 'code': '(?<=\\$)\\d+\n# matches "42" in "$42" — the $ itself is not part of the match\n(?<!not )good\n# "good" in "very good" but not in "not good"', 'note': "JavaScript lookbehind needs ES2018+ (older Safari lacks it); Python's re requires fixed-width lookbehind, while PCRE is more lenient."}, {'repo': 'regex', 'slug': 'email-pattern', 'title': 'A practical regex for email addresses', 'scenario': 'You need to find or sanity-check email addresses in text — without rejecting real ones.', 'code': '[\\w.+-]+@[\\w-]+\\.[\\w.]+\n# matches: name@example.com, first.last+tag@sub.domain.co', 'note': 'No regex validates email perfectly (the RFC is absurd); this loose pattern catches real-world addresses without false rejections.'}, {'repo': 'regex', 'slug': 'url-pattern', 'title': 'A practical regex for finding URLs in text', 'scenario': 'You are scanning text for links.', 'code': 'https?://[^\\s/$.?#].[^\\s]*\n# matches: https://example.com/path?q=1, http://x.io', 'note': 'Good enough for finding links — not for security validation.'}, {'repo': 'regex', 'slug': 'international-phone-pattern', 'title': 'A loose regex for international phone numbers', 'scenario': 'Phone numbers arrive in E.164 style, with or without the leading +.', 'code': '\\+?[1-9]\\d{6,14}\n# matches: +14155552671, 8613800138000 — validate properly server-side', 'note': 'Tolerant by design — validate properly on the server side.'}, {'repo': 'regex', 'slug': 'ipv4-address-strict', 'title': 'A strict regex for IPv4 addresses — every octet really 0-255', 'scenario': 'The loose digit-count version happily accepts 999.999.999.999; you need every octet validated.', 'code': '((25[0-5]|2[0-4]\\d|[01]?\\d\\d?)\\.){3}(25[0-5]|2[0-4]\\d|[01]?\\d\\d?)\n# matches: 192.168.1.1 — rejects 256.1.1.1', 'note': None}, {'repo': 'regex', 'slug': 'date-yyyy-mm-dd-pattern', 'title': 'A regex for dates in YYYY-MM-DD format', 'scenario': 'You want the shape of an ISO date checked quickly.', 'code': '\\d{4}-\\d{2}-\\d{2}\n# matches: 2026-10-09', 'note': 'This checks the format, not the calendar — 2026-13-99 still matches; validate real dates in code.'}, {'repo': 'regex', 'slug': 'html-tag-pattern', 'title': 'A quick regex for HTML tags — and when not to use it', 'scenario': 'A rough scrape needs to spot tags — nothing more.', 'code': '<[^>]+>\n# matches: <p>, </div>, <a href="x">', 'note': None}, {'repo': 'regex', 'slug': 'trim-whitespace-pattern', 'title': 'How to trim leading and trailing whitespace with regex', 'scenario': 'User input arrives padded with spaces and you want the clean middle.', 'code': '^\\s+|\\s+$\n# replace matches with "" → "  hi  " becomes "hi"', 'note': 'Used with a replace-by-empty-string: padded input comes back trimmed.'}, {'repo': 'regex', 'slug': 'replacement-backreferences', 'title': 'Backreferences in replacements — $1 vs \\1, and grep -P in the terminal', 'scenario': 'In the pattern you always write \\1; in the replacement string the spelling depends on the engine — and in the terminal, grep -P gives you PCRE.', 'code': 'pattern:     (\\w+)@(\\w+)\nreplacement: $1 at $2\n# "user@host" → "user at host" (JS/Python style)\necho "user@host" | grep -P -o \'\\w+@\\w+\'   # grep -P = PCRE in the terminal', 'note': 'JavaScript/Python replacements use $1 (Python also \\g<1>); sed/Vim use \\1. Case-conversion escapes work in PCRE/Perl/Vim but not in Python or JavaScript.'}, {'repo': 'regex', 'slug': 'catastrophic-backtracking', 'title': 'Catastrophic backtracking: the regex that hangs — and the fix', 'scenario': 'A pattern like (a+)+$ can take longer than the age of the universe on non-matching input.', 'code': '(a+)+$\n# DANGER: on "aaaaaaaaaaaaaaaaaaaaaaaaaaaaa!" this hangs\n(a+)$\n# safe: one quantifier, linear time', 'note': 'Nested quantifiers make the engine try exponentially many paths. Fix it with atomic groups (PCRE/Java) or rewrite the pattern to be specific — one quantifier, linear time.'}, {'repo': 'regex', 'slug': 'dont-parse-html-with-regex', 'title': 'Why you should not parse HTML with regex', 'scenario': 'Nested tags, comments, CDATA and malformed markup will defeat any pattern eventually — HTML is not a regular language.', 'code': '# <[^>]+> is fine for a quick grep — it is NOT an HTML parser', 'note': "Use a real parser: BeautifulSoup (Python), cheerio (JS), or Go's x/net/html. A tag-spotting pattern is fine for a quick grep — it is not a parser."}, {'repo': 'ssh', 'slug': 'connect-basics-and-ports', 'title': 'How to connect with SSH — custom ports and login names', 'scenario': 'The everyday connection: a user, a host, and — often — a port that is not 22.', 'code': 'ssh deploy@example.com            # default port 22\nssh -p 2222 deploy@example.com    # -p picks the port\nssh -l deploy example.com         # -l = login name (the same as user@)', 'note': None}, {'repo': 'ssh', 'slug': 'login-with-specific-key', 'title': 'How to log in with a specific SSH key — ssh -i', 'scenario': 'You have several keys and this server must get exactly one of them.', 'code': 'ssh -i ~/.ssh/id_ed25519 deploy@example.com   # use exactly this private key', 'note': None}, {'repo': 'ssh', 'slug': 'debug-failed-login-verbose', 'title': 'How to debug a failed SSH login — ssh -v', 'scenario': 'Login fails and the error message tells you nothing; the verbose handshake shows which key was offered and where it ended.', 'code': 'ssh -v deploy@example.com     # watch the handshake; -vv / -vvv for more detail\n# the lines that matter: "Offering public key" → which key was tried,\n# "Authentication succeeded" / "Permission denied" → where it ended', 'note': None}, {'repo': 'ssh', 'slug': 'keepalive-idle-sessions', 'title': 'How to stop SSH sessions from freezing — ServerAliveInterval keepalive', 'scenario': 'Idle sessions keep dying behind NATs and firewalls.', 'code': 'ssh -o ServerAliveInterval=60 -o ServerAliveCountMax=3 deploy@example.com\n# ping the server every 60s; give up after 3 unanswered pings\n# (both are also ~/.ssh/config keywords — see the config section)', 'note': 'The client pings the server every 60 seconds and gives up after 3 unanswered pings. Both options are also ~/.ssh/config keywords.'}, {'repo': 'ssh', 'slug': 'escape-sequences-frozen-session', 'title': 'How to kill a frozen SSH session — the Enter ~. escape', 'scenario': 'The session stopped responding and not even Ctrl+C helps.', 'code': '# type these INSIDE a live (or hung) ssh session; ~ must be the first char after Enter\n<Enter>~.       # disconnect NOW — the rescue for a session that stopped responding\n<Enter>~^Z      # background ssh itself and get your local shell back', 'note': 'Type the sequence inside the live (or hung) session — the ~ must be the first character after Enter. Enter ~^Z backgrounds ssh itself and gives your local shell back.'}, {'repo': 'ssh', 'slug': 'create-ed25519-key', 'title': 'How to create an SSH key pair — ssh-keygen with Ed25519', 'scenario': 'You are setting up key-based login from scratch.', 'code': 'ssh-keygen -t ed25519 -C "you@example.com"\n# private key: ~/.ssh/id_ed25519      → never share it, never commit it\n# public key:  ~/.ssh/id_ed25519.pub  → this is the one you upload\n# set a passphrase: it\'s the second factor protecting the file', 'note': 'The private key never leaves your machine — never share it, never commit it. The .pub file is the one you upload. A passphrase is the second factor protecting the file.'}, {'repo': 'ssh', 'slug': 'install-key-with-copy-id', 'title': 'How to install your public key on a server — ssh-copy-id', 'scenario': 'You log in with your password one last time; after that, the key does it.', 'code': "ssh-copy-id -i ~/.ssh/id_ed25519.pub deploy@example.com\n# appends the key to the server's ~/.ssh/authorized_keys;\n# you log in with your password one last time — after that, the key does it", 'note': None}, {'repo': 'ssh', 'slug': 'ssh-agent-passphrase-once', 'title': 'How to type your key passphrase once per session — ssh-agent and ssh-add', 'scenario': 'Your key has a passphrase and you do not want to type it on every connection.', 'code': 'eval "$(ssh-agent -s)"        # start the agent and load its env vars\nssh-add ~/.ssh/id_ed25519     # unlock a key into the agent\nssh-add -l                    # list the fingerprints the agent holds\nssh-add -D                    # remove ALL keys from the agent', 'note': None}, {'repo': 'ssh', 'slug': 'change-passphrase-and-permissions', 'title': "How to change a key's passphrase — and the file permissions SSH demands", 'scenario': 'The passphrase needs rotating, or SSH refuses to use your key at all.', 'code': 'ssh-keygen -p -f ~/.ssh/id_ed25519   # asks for the old passphrase, then the new one twice\nchmod 700 ~/.ssh\nchmod 600 ~/.ssh/id_ed25519            # ssh REFUSES to use a private key others can read\nchmod 644 ~/.ssh/id_ed25519.pub\nssh-keygen -l -f ~/.ssh/id_ed25519.pub # print the fingerprint — compare before you trust', 'note': 'SSH refuses a private key that others can read: ~/.ssh is 700, the private key 600, the public key 644. ssh-keygen -l prints the fingerprint — compare it before you trust a key.'}, {'repo': 'ssh', 'slug': 'config-host-alias', 'title': 'How to stop typing addresses — ~/.ssh/config host aliases', 'scenario': 'One word should replace user + host + port + key, every single time.', 'code': 'Host web\n    HostName example.com\n    User deploy\n    Port 2222\n    IdentityFile ~/.ssh/id_ed25519\nssh web    # one word now replaces user + host + port + key', 'note': None}, {'repo': 'ssh', 'slug': 'config-global-defaults-host-star', 'title': 'How to set SSH defaults for every host — the Host * block', 'scenario': 'Keepalive and other defaults should apply everywhere, not per server.', 'code': 'Host *\n    ServerAliveInterval 60\n    ServerAliveCountMax 3', 'note': 'ssh_config uses the FIRST value it finds for each keyword — the opposite of most config files. So specific Host blocks go on top, and Host * defaults belong at the bottom of the file.'}, {'repo': 'ssh', 'slug': 'fix-too-many-authentication-failures', 'title': "How to fix SSH 'Too many authentication failures' — IdentitiesOnly", 'scenario': 'Your agent holds many keys and the server rejects you before SSH ever tries the right one.', 'code': 'Host web\n    HostName example.com\n    User deploy\n    IdentityFile ~/.ssh/id_ed25519\n    IdentitiesOnly yes', 'note': None}, {'repo': 'ssh', 'slug': 'config-wildcard-hosts', 'title': 'How to configure a whole fleet with SSH wildcard hosts', 'scenario': 'A fleet shares a user and a key; only the port differs on some of the machines.', 'code': 'Host prod-*\n    User ops\n    IdentityFile ~/.ssh/id_ed25519_prod\n\nHost prod-db-01 prod-web-01\n    Port 2222', 'note': 'ssh prod-db-01 picks up both blocks: user and key from the wildcard block, the port from the explicit list.'}, {'repo': 'ssh', 'slug': 'local-forward-port', 'title': 'How to bring a remote port to your machine — ssh -L local forwarding', 'scenario': 'A service on (or behind) the server should appear on your localhost.', 'code': "ssh -L 8080:localhost:80 deploy@example.com\n# http://localhost:8080 on YOUR machine now hits port 80 on the server\nssh -L 5433:db.internal:5432 deploy@example.com\n# ...or reach a third machine (db.internal) through the server you're logged into", 'note': None}, {'repo': 'ssh', 'slug': 'remote-forward-port', 'title': 'How to expose your local app through a server — ssh -R remote forwarding', 'scenario': 'A colleague needs to test the dev server running on your laptop.', 'code': "ssh -R 9000:localhost:3000 deploy@example.com\n# on the SERVER, localhost:9000 now reaches the app on YOUR localhost:3000\n# default bind is the server's loopback only — other machines can't reach it;\n# exposing it further needs GatewayPorts yes in the SERVER's sshd_config (an admin call, not a client flag)\n# classic use: let a colleague test the dev server running on your laptop", 'note': "By default the forwarded port binds only the server's loopback — other machines cannot reach it. Exposing it further needs GatewayPorts yes in the server's sshd_config, which is an admin call, not a client flag."}, {'repo': 'ssh', 'slug': 'dynamic-forward-socks-proxy', 'title': 'How to turn SSH into a SOCKS proxy — ssh -D dynamic forwarding', 'scenario': "You want your browser's or app's traffic to exit through the server.", 'code': 'ssh -D 1080 deploy@example.com\n# point your browser or app at SOCKS5 proxy localhost:1080 —\n# its traffic exits through the server', 'note': None}, {'repo': 'ssh', 'slug': 'background-tunnel-fn', 'title': 'How to run an SSH tunnel in the background — -fN', 'scenario': 'You need the tunnel, not a shell — and it should fail loudly if the port cannot be bound.', 'code': 'ssh -fN -o ExitOnForwardFailure=yes -L 8080:localhost:80 deploy@example.com\n# -f: background after auth   -N: no remote command, tunnel only\n# ExitOnForwardFailure: exit with an error if the local port can\'t be bound,\n# instead of "working" silently with no tunnel', 'note': "-f backgrounds after authentication, -N runs no remote command. ExitOnForwardFailure makes ssh exit with an error instead of silently 'working' with no tunnel."}, {'repo': 'ssh', 'slug': 'jump-host-proxyjump', 'title': 'How to reach a server through a bastion — ssh -J', 'scenario': 'The target has no public address; you hop through a bastion to reach it.', 'code': 'ssh -J user@bastion.example.com deploy@192.0.2.10              # one hop\nssh -J jump1.example.com,jump2.example.com deploy@192.0.2.10    # chained hops, comma-separated\n# 192.0.2.x is the documentation range — swap in your real internal address', 'note': 'Hops chain with commas. The 192.0.2.x range in the example is the documentation range — swap in your real internal address.'}, {'repo': 'ssh', 'slug': 'proxyjump-in-config', 'title': 'How to bake a jump host into your SSH config — ProxyJump', 'scenario': 'You hop through the same bastion every day and want the hop to happen automatically.', 'code': 'Host bastion\n    HostName bastion.example.com\n    User ec2-user\n    IdentityFile ~/.ssh/id_ed25519\n\nHost internal\n    HostName 192.0.2.10\n    User deploy\n    ProxyJump bastion\nssh internal    # the hop happens automatically —\n                # scp / sftp / rsync to "internal" get it for free too', 'note': 'Once the hop lives in the alias, scp, sftp and rsync to that host get it for free too.'}, {'repo': 'ssh', 'slug': 'scp-copy-files', 'title': 'How to copy files with scp — both directions, custom ports, whole directories', 'scenario': 'A tarball goes up, a log file comes down — or a whole directory tree needs to move.', 'code': 'scp ./app.tar.gz deploy@example.com:/tmp/         # upload\nscp deploy@example.com:/var/log/app.log ./         # download\nscp -P 2222 -r ./site/ deploy@example.com:/var/www/\n# ⚠️ scp\'s port flag is CAPITAL -P; ssh uses lowercase -p.\n# This mix-up is the #1 reason "scp works but ssh doesn\'t" (and vice versa).', 'note': "scp's port flag is CAPITAL -P; ssh uses lowercase -p. This mix-up is the #1 reason 'scp works but ssh doesn't' (and vice versa)."}, {'repo': 'ssh', 'slug': 'rsync-over-ssh', 'title': 'How to sync a directory tree over SSH — rsync -e ssh', 'scenario': 'Only the differences should cross the wire, so re-running after a network drop is cheap.', 'code': 'rsync -avz -e ssh ./site/ deploy@example.com:/var/www/site/\nrsync -avz -e "ssh -p 2222" deploy@example.com:/var/log/ ./logs/\n# only the differences cross the wire, so re-running after a network\n# drop is cheap — the default tool for syncing whole trees over ssh', 'note': None}, {'repo': 'ssh', 'slug': 'sftp-interactive-shell', 'title': 'How to browse and move files interactively — sftp', 'scenario': 'You need an interactive file shell on the server: list, upload, download.', 'code': 'sftp deploy@example.com\nsftp> put ./report.csv /tmp/    # upload\nsftp> get /var/log/app.log      # download\nsftp> ls /var/log               # remote listing (lls = local listing)\nsftp> exit', 'note': None}, {'repo': 'ssh', 'slug': 'disable-root-login', 'title': 'How to disable direct root login over SSH — PermitRootLogin', 'scenario': 'Server hardening, one change at a time: no direct root login — a normal user plus sudo instead.', 'code': 'PermitRootLogin no', 'note': 'Middle ground: PermitRootLogin prohibit-password — root may still log in with a key, never with a password. Hardening rule from the cheatsheet: change one thing at a time, keep your current session open, and prove a fresh login works before you close it.'}, {'repo': 'ssh', 'slug': 'keys-only-no-password-auth', 'title': 'How to turn off SSH password authentication — keys only', 'scenario': 'Passwords are the attack surface; keys should be the only way in.', 'code': 'PubkeyAuthentication yes\nPasswordAuthentication no\nKbdInteractiveAuthentication no', 'note': 'Verify key-based login works in a NEW session first — with passwords off, a lost key means only console access gets you back in. The third line matters: on PAM-based systems the password prompt can survive through keyboard-interactive even with PasswordAuthentication no.'}, {'repo': 'ssh', 'slug': 'restrict-users-and-change-port', 'title': 'How to restrict who can log in — AllowUsers, MaxAuthTries, and changing the port safely', 'scenario': 'Only two accounts should be able to log in at all, failed attempts should be cut off early, and the port move must not lock you out.', 'code': 'AllowUsers deploy ops\nMaxAuthTries 3\nPort 2222\nsudo cp /etc/ssh/sshd_config /etc/ssh/sshd_config.bak   # 1. backup\nsudo sshd -t                                            # 2. syntax check — silence means OK\n# (and open the new port in your firewall before step 3, if you changed it)\nsudo systemctl reload ssh                               # 3a. Debian/Ubuntu: service name is "ssh"\nsudo systemctl reload sshd                              # 3b. RHEL family: service name is "sshd"\n# reload keeps existing sessions alive — verify a fresh login works before logging out', 'note': 'AllowUsers whitelists accounts; MaxAuthTries drops a connection after that many failed attempts (the default is 6). The safe drill: back up the config, syntax-check with sshd -t (silence means OK), open the new port in the firewall if you changed it, then reload — a reload keeps existing sessions alive, and the service is called ssh on Debian/Ubuntu, sshd on the RHEL family.'}, {'repo': 'terminal', 'slug': 'cmux-terminal-for-ai-agents', 'title': 'cmux — the terminal built for AI coding agents', 'scenario': 'You run many AI agents in parallel and lose track of which one needs you.', 'code': 'brew tap manaflow-ai/cmux && brew install --cask cmux   # install\ncmux notify "task done"                                 # try: ping yourself from an agent hook', 'note': 'A native macOS terminal built on Ghostty: vertical tabs, per-agent notification rings so you can see which agent needs you, and a scriptable CLI.'}, {'repo': 'terminal', 'slug': 'yoinks-download-videos', 'title': 'yoinks — download videos from your terminal', 'scenario': 'You want a video from YouTube, X/Twitter, Instagram, Threads, TikTok or 1,800+ other sites — without popups and fake download buttons.', 'code': 'npm install -g yoinks   # install (needs Node 18+)\nyoinks                  # try: paste any video URL when prompted', 'note': 'Needs Node 18+. Paste a URL, pick a resolution (or audio-only mp3), done.'}, {'repo': 'terminal', 'slug': 'zoxide-smarter-cd', 'title': 'zoxide — a smarter cd that remembers where you go', 'scenario': 'You keep typing long paths to the same three projects; zoxide remembers the directories you visit most and jumps to them from a fragment.', 'code': 'brew install zoxide                      # install\neval "$(zoxide init zsh)" >> ~/.zshrc    # hook into your shell\nz proj                                   # try: jump to best match for "proj"', 'note': None}, {'repo': 'terminal', 'slug': 'fzf-fuzzy-finder', 'title': 'fzf — fuzzy-find files, history and processes as you type', 'scenario': 'You can name half of the thing you are looking for — a file, a past command, a process.', 'code': 'brew install fzf   # install\nvim $(fzf)         # try: pick a file to open (or press Ctrl-R for history)', 'note': None}, {'repo': 'terminal', 'slug': 'fd-friendlier-find', 'title': "fd — find files without fighting find's syntax", 'scenario': 'You want every Python file under config/ — with sane defaults, colorized output, and regex you can actually read.', 'code': 'brew install fd        # install\nfd -e py config        # try: find all *.py files under config/', 'note': None}, {'repo': 'terminal', 'slug': 'ripgrep-grep-rebuilt-in-rust', 'title': 'ripgrep — grep, rebuilt in Rust', 'scenario': 'You need every TODO in src/ — across the whole codebase, in milliseconds.', 'code': 'brew install ripgrep   # install\nrg "TODO" src/         # try: find every TODO in src/', 'note': 'ripgrep respects .gitignore by default and prints results you can read.'}, {'repo': 'terminal', 'slug': 'tmux-terminal-multiplexer', 'title': 'tmux — terminal sessions that survive disconnects', 'scenario': 'Your work lives on remote servers: split panes, persistent sessions, detach and reattach over SSH.', 'code': 'brew install tmux      # macOS — or: sudo apt install tmux\ntmux new -s work        # try: new session named "work" (Ctrl-b % splits, Ctrl-b d detaches)', 'note': None}, {'repo': 'terminal', 'slug': 'zellij-modern-multiplexer', 'title': 'zellij — a modern terminal workspace, tmux with training wheels', 'scenario': "You want tmux's power with discoverable keybindings, layouts, floating panes, and sessions that survive restarts.", 'code': 'brew install zellij   # install\nzellij -s dev         # try: start a session named "dev"', 'note': None}, {'repo': 'terminal', 'slug': 'starship-prompt', 'title': 'starship — a shell prompt that tells you things', 'scenario': 'Git branch and status, language versions, command duration — right where you look, in a minimal, fast, customizable prompt.', 'code': 'brew install starship                    # install\neval "$(starship init zsh)" >> ~/.zshrc  # hook into your shell, then cd into any git repo', 'note': None}, {'repo': 'terminal', 'slug': 'eza-modern-ls', 'title': 'eza — ls with colors, icons and git status', 'scenario': 'Plain ls tells you filenames and nothing else; eza is its maintained successor (the exa lineage).', 'code': 'brew install eza          # install\neza -la --icons --git     # try: long listing with icons and git status', 'note': None}, {'repo': 'terminal', 'slug': 'bat-cat-with-highlighting', 'title': 'bat — cat with syntax highlighting and line numbers', 'scenario': 'You open a source file just to read it, and plain cat gives you a wall of unformatted text.', 'code': 'brew install bat   # install\nbat main.py        # try: view any source file', 'note': 'bat pipes code through highlighting, line numbers, and git markers. Once you use it, plain cat feels broken.'}, {'repo': 'terminal', 'slug': 'lazygit-terminal-ui', 'title': 'lazygit — git, without the memorization', 'scenario': 'Stage individual hunks, do interactive rebases, resolve conflicts, manage branches — all without leaving the keyboard.', 'code': 'brew install lazygit   # install\nlazygit                # try: run it inside any git repo', 'note': None}, {'repo': 'terminal', 'slug': 'tldr-man-pages-you-will-read', 'title': 'tldr — man pages you will actually read', 'scenario': "You need tar's flags, not tar's archaeology: community cheatsheets that are short and example-first.", 'code': "brew install tldr   # install, then: tldr --update\ntldr tar            # try: finally understand tar's flags", 'note': None}, {'repo': 'terminal', 'slug': 'btop-resource-monitor', 'title': 'btop — a resource monitor worth looking at', 'scenario': 'CPU, memory, disks, network and processes in one terminal UI — top for people with eyes.', 'code': "brew install btop   # macOS — or: sudo apt install btop\nbtop                # try: that's it, just look at it", 'note': None}, {'repo': 'terminal', 'slug': 'starter-pack-one-command', 'title': 'The terminal starter pack — install the whole set with one Homebrew command', 'scenario': 'You are setting up a new Mac and want all twelve tools in one shot.', 'code': 'brew install zoxide fzf fd ripgrep eza bat starship lazygit tldr btop tmux zellij', 'note': None}, {'repo': 'terminal', 'slug': 'navigate-faster-zoxide-fzf', 'title': 'Jump and find: zoxide + fzf for terminal navigation', 'scenario': 'Jump to the project from a fragment, then fuzzy-pick the file inside it.', 'code': 'brew install zoxide                      # install\neval "$(zoxide init zsh)" >> ~/.zshrc    # hook into your shell\nz proj                                   # try: jump to best match for "proj"\nbrew install fzf   # install\nvim $(fzf)         # try: pick a file to open (or press Ctrl-R for history)', 'note': None}, {'repo': 'terminal', 'slug': 'find-and-search-fd-ripgrep', 'title': 'Find files, then search inside them — fd + ripgrep', 'scenario': 'First locate the files with fd, then search their contents across the whole tree with ripgrep.', 'code': 'brew install fd        # install\nfd -e py config        # try: find all *.py files under config/\nbrew install ripgrep   # install\nrg "TODO" src/         # try: find every TODO in src/', 'note': None}, {'repo': 'terminal', 'slug': 'view-files-eza-bat', 'title': 'Read files properly: eza to list, bat to view', 'scenario': 'List the directory with icons and git status, then read the file with highlighting and line numbers.', 'code': 'brew install eza          # install\neza -la --icons --git     # try: long listing with icons and git status\nbrew install bat   # install\nbat main.py        # try: view any source file', 'note': None}, {'repo': 'terminal', 'slug': 'tmux-vs-zellij', 'title': 'tmux vs zellij — which terminal multiplexer?', 'scenario': 'Both split panes and keep sessions alive: the classic you configure yourself, or the modern one that teaches you its keys as you go.', 'code': 'brew install tmux      # macOS — or: sudo apt install tmux\ntmux new -s work        # try: new session named "work" (Ctrl-b % splits, Ctrl-b d detaches)\nbrew install zellij   # install\nzellij -s dev         # try: start a session named "dev"', 'note': None}, {'repo': 'terminal', 'slug': 'git-workflow-lazygit-starship', 'title': 'A git workflow that stays in the terminal — lazygit + starship', 'scenario': 'The prompt tells you the branch and the working-tree state; lazygit handles staging, rebasing and conflicts — no context switch to a GUI.', 'code': 'brew install lazygit   # install\nlazygit                # try: run it inside any git repo\nbrew install starship                    # install\neval "$(starship init zsh)" >> ~/.zshrc  # hook into your shell, then cd into any git repo', 'note': None}, {'repo': 'terminal', 'slug': 'remote-sessions-tmux-zoxide', 'title': 'Remote work over SSH — tmux sessions plus zoxide jumps', 'scenario': 'You live on remote servers: sessions that survive the disconnect, and instant jumps to the directories you actually use there.', 'code': 'brew install tmux      # macOS — or: sudo apt install tmux\ntmux new -s work        # try: new session named "work" (Ctrl-b % splits, Ctrl-b d detaches)\nbrew install zoxide                      # install\neval "$(zoxide init zsh)" >> ~/.zshrc    # hook into your shell\nz proj                                   # try: jump to best match for "proj"', 'note': None}, {'repo': 'terminal', 'slug': 'monitor-with-btop-in-tmux', 'title': 'Watch the machine while you work — btop in a tmux pane', 'scenario': 'One pane runs the work, another keeps CPU, memory, disks and processes in sight.', 'code': 'brew install btop   # macOS — or: sudo apt install btop\nbtop                # try: that\'s it, just look at it\nbrew install tmux      # macOS — or: sudo apt install tmux\ntmux new -s work        # try: new session named "work" (Ctrl-b % splits, Ctrl-b d detaches)', 'note': None}, {'repo': 'terminal', 'slug': 'new-in-2026-cmux-yoinks', 'title': 'New in 2026: cmux and yoinks', 'scenario': 'The two newest entries on the list: a terminal built for parallel AI agents, and a terminal video downloader covering 1,800+ sites.', 'code': 'brew tap manaflow-ai/cmux && brew install --cask cmux   # install\ncmux notify "task done"                                 # try: ping yourself from an agent hook\nnpm install -g yoinks   # install (needs Node 18+)\nyoinks                  # try: paste any video URL when prompted', 'note': None}, {'repo': 'terminal', 'slug': 'replace-classic-unix-tools', 'title': 'Replace the classics: find, ls, cat and grep — with fd, eza, bat and ripgrep', 'scenario': 'Four everyday commands, four modern successors with sane defaults and output you can read.', 'code': 'brew install fd        # install\nfd -e py config        # try: find all *.py files under config/\nbrew install eza          # install\neza -la --icons --git     # try: long listing with icons and git status\nbrew install bat   # install\nbat main.py        # try: view any source file\nbrew install ripgrep   # install\nrg "TODO" src/         # try: find every TODO in src/', 'note': None}, {'repo': 'terminal', 'slug': 'learn-commands-tldr-fzf', 'title': 'Learn any command fast — tldr examples plus fzf history search', 'scenario': 'tldr shows you the examples that matter; Ctrl-R with fzf finds the command you ran last month.', 'code': "brew install tldr   # install, then: tldr --update\ntldr tar            # try: finally understand tar's flags\nbrew install fzf   # install\nvim $(fzf)         # try: pick a file to open (or press Ctrl-R for history)", 'note': None}, {'repo': 'adobe', 'slug': 'photocraft-alternative-to-photoshop', 'title': 'Free alternative to Photoshop — PhotoCraft (early alpha)', 'scenario': 'You want Photoshop-style image editing — layers, masks, text, PSD read and write — without the subscription.', 'code': 'cargo run --release', 'note': 'Early alpha. An open-source image editor written in Rust; download from GitHub Releases or build from source with the command above. macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'vectorcraft-alternative-to-illustrator', 'title': 'Free alternative to Illustrator — VectorCraft (early alpha)', 'scenario': 'Vector illustration with a pen tool and image tracing (the tool formerly known as DrawCraft).', 'code': 'cargo run --release', 'note': 'Early alpha. Rust and open source; GitHub Releases download or source build. macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'filmcraft-alternative-to-premiere', 'title': 'Free alternative to Premiere Pro — FilmCraft (early alpha)', 'scenario': 'Video editing, color grading and audio in one native Rust app.', 'code': 'cargo run --release', 'note': 'Early alpha. GitHub Releases download or source build. macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'lightcraft-alternative-to-lightroom', 'title': 'Free alternative to Lightroom — LightCraft (early alpha)', 'scenario': 'Photo library management and RAW development, free and open source.', 'code': 'cargo run --release', 'note': 'Early alpha. GitHub Releases download or source build. macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'printcraft-alternative-to-acrobat', 'title': 'Free alternative to Acrobat — PrintCraft (early alpha)', 'scenario': 'Read, merge, split and protect PDFs without an Acrobat subscription.', 'code': 'cargo run --release', 'note': 'Early alpha. GitHub Releases download or source build. macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'effectcraft-alternative-to-after-effects', 'title': 'Free alternative to After Effects — EffectCraft (early alpha)', 'scenario': 'Motion graphics and visual effects in a free Rust app.', 'code': 'cargo run --release', 'note': 'Early alpha. GitHub Releases download or source build. macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'designcraft-alternative-to-indesign', 'title': 'Free alternative to InDesign — DesignCraft (early alpha)', 'scenario': 'Page layout and publishing without the InDesign subscription.', 'code': 'cargo run --release', 'note': 'Early alpha. GitHub Releases download or source build. macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'gimp-alternative-to-photoshop', 'title': 'Free alternative to Photoshop — GIMP (mature)', 'scenario': 'The classic open-source image editor: layers, channels and filters for almost everything, with twenty-plus years of development behind it.', 'code': 'brew install --cask gimp', 'note': 'Mature and free/open source. Windows / macOS / Linux.'}, {'repo': 'adobe', 'slug': 'inkscape-alternative-to-illustrator', 'title': 'Free alternative to Illustrator — Inkscape (mature)', 'scenario': 'A professional vector editor with native SVG, path operations, clones and symbols.', 'code': 'brew install inkscape', 'note': 'Mature and free/open source. Windows / macOS / Linux.'}, {'repo': 'adobe', 'slug': 'davinci-resolve-alternative-to-premiere', 'title': 'Free alternative to Premiere Pro — DaVinci Resolve (mature)', 'scenario': 'Hollywood-grade color grading and editing; the free version already covers most needs.', 'code': 'https://www.blackmagicdesign.com/products/davinciresolve', 'note': 'Mature. Free (the Studio version is paid). Download the installer from the official site above. macOS / Windows / Linux.'}, {'repo': 'adobe', 'slug': 'kdenlive-alternative-to-premiere', 'title': 'Free alternative to Premiere Pro — Kdenlive (mature)', 'scenario': "KDE's multi-track video editor: light, stable, and plays every format via FFmpeg.", 'code': 'brew install --cask kdenlive', 'note': 'Mature and free/open source. Linux / Windows / macOS.'}, {'repo': 'adobe', 'slug': 'darktable-alternative-to-lightroom', 'title': 'Free alternative to Lightroom — darktable (mature)', 'scenario': 'An open-source photography workflow: RAW development and photo management, fully non-destructive editing.', 'code': 'brew install --cask darktable', 'note': 'Mature and free/open source. Linux / macOS / Windows.'}, {'repo': 'adobe', 'slug': 'audacity-alternative-to-audition', 'title': 'Free alternative to Audition — Audacity (mature)', 'scenario': 'Multi-track recording and audio editing — the podcast and voice-over staple.', 'code': 'brew install --cask audacity', 'note': 'Mature and free/open source. Windows / macOS / Linux.'}, {'repo': 'adobe', 'slug': 'blender-alternative-to-after-effects', 'title': 'Free alternative to After Effects — Blender (mature)', 'scenario': 'A full free 3D pipeline — modeling, animation, rendering, compositing — with a video editor built in.', 'code': 'brew install --cask blender', 'note': 'Mature and free/open source. Windows / macOS / Linux.'}, {'repo': 'adobe', 'slug': 'penpot-alternative-to-figma-xd', 'title': 'Free alternative to Figma and Adobe XD — Penpot (mature)', 'scenario': 'Open-source interface design and prototyping in the browser, with native SVG — the design is code.', 'code': 'https://penpot.app', 'note': 'Mature. Free cloud tier, or self-host the open-source version (see the docs on the official site). Runs in the browser / Docker.'}, {'repo': 'adobe', 'slug': 'scribus-alternative-to-indesign', 'title': 'Free alternative to InDesign — Scribus (mature)', 'scenario': 'Open-source desktop publishing with CMYK, spot colors and ICC color management — print-ready PDF output.', 'code': 'brew install --cask scribus', 'note': 'Mature and free/open source. Linux / macOS / Windows.'}, {'repo': 'adobe', 'slug': 'photoshop-alternatives-compared', 'title': 'Free alternatives to Photoshop — PhotoCraft and GIMP', 'scenario': 'Two ways to stop paying for Photoshop: the new Rust editor (alpha) or the mature classic.', 'code': 'cargo run --release\nbrew install --cask gimp', 'note': 'PhotoCraft reads and writes PSD and is moving fast, but it is early alpha; GIMP is the safe production pick today. Both run on macOS / Windows / Linux.'}, {'repo': 'adobe', 'slug': 'illustrator-alternatives-compared', 'title': 'Free alternatives to Illustrator — VectorCraft and Inkscape', 'scenario': 'Vector work without the subscription: an alpha newcomer or the SVG-native veteran.', 'code': 'cargo run --release\nbrew install inkscape', 'note': 'VectorCraft brings a pen tool and image tracing in a modern Rust app; Inkscape is the mature professional editor. Both free and open source.'}, {'repo': 'adobe', 'slug': 'premiere-alternatives-compared', 'title': 'Free alternatives to Premiere Pro — FilmCraft, DaVinci Resolve and Kdenlive', 'scenario': "Three free editors: a Rust alpha, Hollywood's free tier, and KDE's lightweight multi-track editor.", 'code': 'cargo run --release\nhttps://www.blackmagicdesign.com/products/davinciresolve\nbrew install --cask kdenlive', 'note': "DaVinci Resolve's free version already covers most editing and grading needs; Kdenlive is the open-source lightweight option; FilmCraft is the one to watch."}, {'repo': 'adobe', 'slug': 'lightroom-alternatives-compared', 'title': 'Free alternatives to Lightroom — LightCraft and darktable', 'scenario': 'RAW development and photo management, free either way: a new alpha or a mature workflow.', 'code': 'cargo run --release\nbrew install --cask darktable', 'note': 'darktable is fully non-destructive and battle-tested; LightCraft is the Rust newcomer from the same suite as PhotoCraft.'}, {'repo': 'adobe', 'slug': 'after-effects-alternatives-compared', 'title': 'Free alternatives to After Effects — EffectCraft and Blender', 'scenario': 'Motion graphics and VFX without the subscription: a Rust alpha, or the full 3D suite that also edits video.', 'code': 'cargo run --release\nbrew install --cask blender', 'note': 'Blender covers modeling, animation, rendering and compositing in one free package; EffectCraft focuses on motion graphics and is early alpha.'}, {'repo': 'adobe', 'slug': 'indesign-alternatives-compared', 'title': 'Free alternatives to InDesign — DesignCraft and Scribus', 'scenario': 'Page layout and print-ready output without the subscription.', 'code': 'cargo run --release\nbrew install --cask scribus', 'note': 'Scribus brings CMYK/spot-color and ICC color management for print work today; DesignCraft is the alpha in the Rust suite.'}, {'repo': 'adobe', 'slug': 'artcraft-suite-seven-apps', 'title': 'The ArtCraft suite — seven Rust apps that replace the Adobe suite', 'scenario': 'One team rewrote the Adobe suite in Rust: PhotoCraft (Photoshop), VectorCraft (Illustrator), FilmCraft (Premiere Pro), LightCraft (Lightroom), PrintCraft (Acrobat), EffectCraft (After Effects) and DesignCraft (InDesign).', 'code': 'cargo run --release', 'note': 'All seven are early alpha — good for exploring, not yet for production deadlines. Each installs the same way: download from GitHub Releases, or build from source with the command above. All run on macOS / Windows / Linux / web.'}, {'repo': 'adobe', 'slug': 'mature-free-creative-suite', 'title': 'The mature free creative suite — GIMP, Inkscape, Kdenlive, darktable, Audacity, Blender, Scribus', 'scenario': 'Skip the alphas: the established free tools that already cover photo, vector, video, RAW, audio, 3D and layout today.', 'code': 'brew install --cask gimp\nbrew install inkscape\nbrew install --cask kdenlive\nbrew install --cask darktable\nbrew install --cask audacity\nbrew install --cask blender\nbrew install --cask scribus', 'note': 'Add DaVinci Resolve (installer from its official site) and Penpot (in the browser) and the suite is complete — every entry free, every entry mature.'}, {'repo': 'adobe', 'slug': 'install-alternatives-on-linux', 'title': 'How to install the free Adobe alternatives on Linux', 'scenario': "The cheatsheet's install commands are Homebrew (macOS) — on Linux the same tools come from apt.", 'code': '> Linux 用户：macOS 的 `brew install --cask X` 对应 `sudo apt install <小写包名>`（如 `sudo apt install gimp`）。', 'note': "The cheatsheet's own note (Chinese, above): a macOS brew install --cask X corresponds to sudo apt install <lowercase package name> on Linux — for example sudo apt install gimp."}, {'repo': 'desubscribe', 'slug': 'replace-notion-with-appflowy', 'title': 'Replace Notion Plus ($120/yr) with AppFlowy — free and self-hosted', 'scenario': 'Notes, documents, databases and boards — with your data on your own server instead of a per-person subscription.', 'code': 'git clone https://github.com/AppFlowy-IO/AppFlowy-SelfHost-Commercial && cd AppFlowy-SelfHost-Commercial && cp deploy.env .env && docker compose up -d', 'note': "AppFlowy's self-hosted edition lives in the AppFlowy-SelfHost-Commercial repo and includes a free tier. Prefer zero servers? The cheatsheet's other pick, Anytype, is local-first with P2P sync — no server to install at all."}, {'repo': 'desubscribe', 'slug': 'replace-slack-with-mattermost', 'title': 'Replace Slack Pro ($87/yr per person) with Mattermost — save $87 a year', 'scenario': 'Team chat — channels, direct messages, bots, webhooks — that feels almost identical to Slack, hosted by you.', 'code': 'git clone https://github.com/mattermost/docker && cd docker && docker compose -f docker-compose.yml -f docker-compose.without-nginx.yml up -d', 'note': 'After it starts, open http://localhost:8065 and create the admin account. For a 10-person team this swap alone saves $870 a year.'}, {'repo': 'desubscribe', 'slug': 'replace-figma-with-penpot', 'title': 'Replace Figma Professional ($144/yr per editor) with Penpot — save $144 a year', 'scenario': 'Design collaboration on an open platform built on native SVG/CSS standards — designs that produce usable code.', 'code': 'curl -o docker-compose.yaml https://raw.githubusercontent.com/penpot/penpot/main/docker/images/docker-compose.yaml && docker compose -p penpot -f docker-compose.yaml up -d', 'note': 'After it starts, open http://localhost:9001.'}, {'repo': 'desubscribe', 'slug': 'replace-google-one-with-immich', 'title': 'Replace Google One 2TB ($100/yr) with Immich — save $100 a year', 'scenario': 'Photo and video backup with automatic phone uploads, AI search and face recognition — on your own hard drives.', 'code': 'mkdir immich && cd immich && wget -O docker-compose.yml https://github.com/immich-app/immich/releases/latest/download/docker-compose.yml && wget -O .env https://github.com/immich-app/immich/releases/latest/download/example.env && docker compose up -d', 'note': 'After it starts, open http://localhost:2283 and connect the mobile app for automatic backup.'}, {'repo': 'desubscribe', 'slug': 'replace-1password-with-vaultwarden', 'title': 'Replace 1Password ($48/yr) with Vaultwarden — save $48 a year', 'scenario': 'A password server the official Bitwarden clients (phone, browser, desktop) all connect to — written in Rust and extremely light.', 'code': 'docker run -d --name vaultwarden -v /vw-data/:/data/ --restart unless-stopped -p 80:80 vaultwarden/server:latest', 'note': None}, {'repo': 'desubscribe', 'slug': 'replace-dropbox-with-nextcloud', 'title': 'Replace Dropbox Plus ($120/yr) with Nextcloud — save $120 a year', 'scenario': 'Not just file sync: calendar, contacts and online documents — a private cloud you host yourself.', 'code': 'docker run -d --name nextcloud -p 8080:80 -v nextcloud-data:/var/www/html --restart unless-stopped nextcloud', 'note': 'After it starts, open http://localhost:8080 and follow the wizard to create the admin account.'}, {'repo': 'desubscribe', 'slug': 'replace-airtable-with-nocodb', 'title': 'Replace Airtable Team ($240/yr per seat) with NocoDB — save $240 a year', 'scenario': 'Any SQL database turned into a smart spreadsheet in seconds, with a REST API included.', 'code': 'docker run -d --name noco -v "$(pwd)"/nocodb:/usr/app/data/ -p 8080:8080 --restart unless-stopped nocodb/nocodb:latest', 'note': 'At $240 per seat per year, Airtable is the most expensive line in the cheatsheet — this is the single biggest swap.'}, {'repo': 'desubscribe', 'slug': 'replace-trello-with-wekan', 'title': 'Replace Trello Premium ($120/yr per person) with Wekan — save $120 a year', 'scenario': 'Boards, cards, checklists and swimlanes — Trello users need zero learning time.', 'code': 'docker network create wekan-net\ndocker run -d --name wekan-db --network wekan-net --restart=always mongo:5\ndocker run -d --name wekan --network wekan-net --restart=always \\\n  -e MONGO_URL=mongodb://wekan-db:27017/wekan \\\n  -e ROOT_URL=http://localhost:8080 -p 8080:8080 wekanteam/wekan', 'note': 'Wekan needs MongoDB alongside it, so this swap is a few commands, not one.'}, {'repo': 'desubscribe', 'slug': 'replace-zoom-with-jitsi', 'title': 'Replace Zoom Pro ($150/yr) with Jitsi Meet — save $150 a year', 'scenario': 'Video meetings in the browser — no registration, end-to-end encryption, and self-hosted means no participant limits either.', 'code': 'git clone https://github.com/jitsi/docker-jitsi-meet && cd docker-jitsi-meet && cp env.example .env && docker compose up -d', 'note': None}, {'repo': 'desubscribe', 'slug': 'replace-evernote-with-joplin', 'title': 'Replace Evernote Personal ($130/yr) with Joplin — save $130 a year', 'scenario': 'Markdown notes with web clipping and end-to-end encryption, with apps on every platform.', 'code': 'docker run -d --name joplin -p 22300:22300 -e APP_PORT=22300 -e APP_BASE_URL=http://localhost:22300 --restart unless-stopped joplin/server:latest', 'note': "The one-command install uses SQLite by default, which is fine to start; for serious use, switch it to Postgres (see Joplin's official docs)."}, {'repo': 'desubscribe', 'slug': 'wekan-full-install-with-mongodb', 'title': 'How to install Wekan with its MongoDB — the full command set', 'scenario': 'The Trello replacement is the one swap that needs two containers: the app and its database, on their own Docker network.', 'code': 'docker network create wekan-net\ndocker run -d --name wekan-db --network wekan-net --restart=always mongo:5\ndocker run -d --name wekan --network wekan-net --restart=always \\\n  -e MONGO_URL=mongodb://wekan-db:27017/wekan \\\n  -e ROOT_URL=http://localhost:8080 -p 8080:8080 wekanteam/wekan', 'note': None}, {'repo': 'desubscribe', 'slug': 'total-savings-1260-a-year', 'title': 'How much do the 10 swaps save in total? About $1,260 a year', 'scenario': 'Ten SaaS subscriptions cost about $1,260 per person per year; one $5/month VPS runs all ten replacements — a net saving of about $1,200 a year.', 'code': '| 10 个 SaaS 订阅 | 约 $1,260/人/年 |\n| 1 台小 VPS（全装下） | 约 $60/年 |\n| **净省** | **约 $1,200/人/年** |', 'note': "The cheatsheet's own ledger (Chinese table above): 10 SaaS subscriptions at roughly $1,260 per person per year; one small VPS at roughly $60 a year; net saving roughly $1,200 per person per year."}, {'repo': 'desubscribe', 'slug': 'team-savings-4470', 'title': 'What does a 10-person team save? $4,470 a year on three tools alone', 'scenario': 'Per-person pricing multiplies fast: Slack, Notion and Airtable for ten people.', 'code': '团队版更夸张：10 人团队光 Slack + Notion + Airtable 一年就省 **$4,470**。', 'note': "In the cheatsheet's words (Chinese, above): the team math is wilder — a 10-person team saves $4,470 a year on Slack + Notion + Airtable alone."}, {'repo': 'desubscribe', 'slug': 'five-year-cost-of-subscriptions', 'title': 'What do subscriptions really cost? $6,300 over five years', 'scenario': 'One person, ten ordinary subscriptions: $1,260 a year becomes $6,300 in five years.', 'code': '> 一个普通人一年在 SaaS 订阅上花 **$1,260**，五年就是 **$6,300**。', 'note': "The cheatsheet's opening math (Chinese, above): an ordinary person spends about $1,260 a year on SaaS subscriptions — $6,300 in five years — while the replacements run on one $5/month VPS, all free."}, {'repo': 'desubscribe', 'slug': 'notes-stack-appflowy-joplin', 'title': 'Replace your notes stack — Notion + Evernote with AppFlowy + Joplin (save $250/yr)', 'scenario': 'Two note subscriptions, two self-hosted replacements: docs and boards in AppFlowy, the long-term archive in Joplin.', 'code': 'git clone https://github.com/AppFlowy-IO/AppFlowy-SelfHost-Commercial && cd AppFlowy-SelfHost-Commercial && cp deploy.env .env && docker compose up -d\ndocker run -d --name joplin -p 22300:22300 -e APP_PORT=22300 -e APP_BASE_URL=http://localhost:22300 --restart unless-stopped joplin/server:latest', 'note': None}, {'repo': 'desubscribe', 'slug': 'files-and-photos-stack', 'title': 'Replace your file stack — Google One + Dropbox with Immich + Nextcloud (save $220/yr)', 'scenario': 'Photos go to Immich, everything else to Nextcloud — both on hardware you own.', 'code': 'mkdir immich && cd immich && wget -O docker-compose.yml https://github.com/immich-app/immich/releases/latest/download/docker-compose.yml && wget -O .env https://github.com/immich-app/immich/releases/latest/download/example.env && docker compose up -d\ndocker run -d --name nextcloud -p 8080:80 -v nextcloud-data:/var/www/html --restart unless-stopped nextcloud', 'note': None}, {'repo': 'desubscribe', 'slug': 'team-chat-and-boards-stack', 'title': 'Replace your team stack — Slack + Trello with Mattermost + Wekan (save $207/yr per person)', 'scenario': 'Chat and boards are the two subscriptions every small team pays for first.', 'code': 'git clone https://github.com/mattermost/docker && cd docker && docker compose -f docker-compose.yml -f docker-compose.without-nginx.yml up -d\ndocker network create wekan-net\ndocker run -d --name wekan-db --network wekan-net --restart=always mongo:5\ndocker run -d --name wekan --network wekan-net --restart=always \\\n  -e MONGO_URL=mongodb://wekan-db:27017/wekan \\\n  -e ROOT_URL=http://localhost:8080 -p 8080:8080 wekanteam/wekan', 'note': None}, {'repo': 'desubscribe', 'slug': 'meetings-and-design-stack', 'title': 'Replace meetings and design — Zoom + Figma with Jitsi + Penpot (save $294/yr)', 'scenario': 'Browser-based meetings with no attendee limits, and design collaboration on open standards.', 'code': 'git clone https://github.com/jitsi/docker-jitsi-meet && cd docker-jitsi-meet && cp env.example .env && docker compose up -d\ncurl -o docker-compose.yaml https://raw.githubusercontent.com/penpot/penpot/main/docker/images/docker-compose.yaml && docker compose -p penpot -f docker-compose.yaml up -d', 'note': None}, {'repo': 'desubscribe', 'slug': 'biggest-savings-first', 'title': 'The three biggest subscription savings — Airtable, Zoom, Figma ($534/yr)', 'scenario': 'If you only do three swaps, do these: $240 + $150 + $144 a year back.', 'code': 'docker run -d --name noco -v "$(pwd)"/nocodb:/usr/app/data/ -p 8080:8080 --restart unless-stopped nocodb/nocodb:latest\ngit clone https://github.com/jitsi/docker-jitsi-meet && cd docker-jitsi-meet && cp env.example .env && docker compose up -d\ncurl -o docker-compose.yaml https://raw.githubusercontent.com/penpot/penpot/main/docker/images/docker-compose.yaml && docker compose -p penpot -f docker-compose.yaml up -d', 'note': None}, {'repo': 'desubscribe', 'slug': 'cheapest-swaps-to-start', 'title': 'The two easiest swaps to start with — 1Password and Slack ($135/yr)', 'scenario': 'Lowest-risk first tries: a password server that takes a single docker run, and a chat server your team already knows how to use.', 'code': 'docker run -d --name vaultwarden -v /vw-data/:/data/ --restart unless-stopped -p 80:80 vaultwarden/server:latest\ngit clone https://github.com/mattermost/docker && cd docker && docker compose -f docker-compose.yml -f docker-compose.without-nginx.yml up -d', 'note': None}, {'repo': 'desubscribe', 'slug': 'what-you-need-to-self-host', 'title': 'What do you need to self-host all of this? One small server', 'scenario': 'An old PC, a Raspberry Pi, a NAS or a cloud VPS — the data is yours, and so are the backups and the security.', 'code': '- 自托管需要一台服务器：旧电脑、树莓派、NAS 或云 VPS 都行；数据归你，但备份和安全自己负责。\n**合计：约 $1,260 /人/年** —— 一台 $5/月的小 VPS（$60/年）全装下，净省 $1,200。', 'note': "Both lines are the cheatsheet's own words (Chinese): self-hosting needs one server — old PC, Raspberry Pi, NAS or cloud VPS; the data is yours, but backups and security are your responsibility too."}, {'repo': 'desubscribe', 'slug': 'are-these-prices-current', 'title': 'Are these subscription prices still current?', 'scenario': 'The cheatsheet verified every price against the official pricing pages in October 2026, on annual billing.', 'code': '- 价格为 2026 年 10 月核实的各官网定价（年付口径），SaaS 经常调价，动手前请以官网为准。', 'note': 'Its own caveat (Chinese, above): prices were verified in October 2026 on annual plans; SaaS vendors change prices often — check the official site before you act.'}, {'repo': 'desubscribe', 'slug': 'free-tiers-honest-note', 'title': "Do the 'free' replacements have paid tiers? The honest note", 'scenario': 'Some replacements include a free tier inside a commercial offering — the free tier is plenty for individuals and small teams.', 'code': '- 有些替代品（如 AppFlowy 自托管新版）含免费层/商业版，免费额度内的个人/小团队使用完全够用。', 'note': "The cheatsheet's honesty note (Chinese, above): some replacements (such as AppFlowy's newer self-hosted edition) include a free tier / commercial edition; within the free tier, personal and small-team use is fully covered."}, {'repo': 'desubscribe', 'slug': 'passwords-and-data-stack', 'title': 'Replace passwords and business data — 1Password + Airtable with Vaultwarden + NocoDB (save $288/yr)', 'scenario': 'The two most sensitive categories — credentials and business data — are exactly the ones worth bringing in-house.', 'code': 'docker run -d --name vaultwarden -v /vw-data/:/data/ --restart unless-stopped -p 80:80 vaultwarden/server:latest\ndocker run -d --name noco -v "$(pwd)"/nocodb:/usr/app/data/ -p 8080:8080 --restart unless-stopped nocodb/nocodb:latest', 'note': None}, {'repo': 'desubscribe', 'slug': 'run-all-ten-replacements', 'title': 'Run all 10 free replacements on one VPS — every install command', 'scenario': 'The whole cheatsheet on one page: ten subscriptions out, ten self-hosted apps in, about $1,200 a year saved.', 'code': 'git clone https://github.com/AppFlowy-IO/AppFlowy-SelfHost-Commercial && cd AppFlowy-SelfHost-Commercial && cp deploy.env .env && docker compose up -d\ngit clone https://github.com/mattermost/docker && cd docker && docker compose -f docker-compose.yml -f docker-compose.without-nginx.yml up -d\ncurl -o docker-compose.yaml https://raw.githubusercontent.com/penpot/penpot/main/docker/images/docker-compose.yaml && docker compose -p penpot -f docker-compose.yaml up -d\nmkdir immich && cd immich && wget -O docker-compose.yml https://github.com/immich-app/immich/releases/latest/download/docker-compose.yml && wget -O .env https://github.com/immich-app/immich/releases/latest/download/example.env && docker compose up -d\ndocker run -d --name vaultwarden -v /vw-data/:/data/ --restart unless-stopped -p 80:80 vaultwarden/server:latest\ndocker run -d --name nextcloud -p 8080:80 -v nextcloud-data:/var/www/html --restart unless-stopped nextcloud\ndocker run -d --name noco -v "$(pwd)"/nocodb:/usr/app/data/ -p 8080:8080 --restart unless-stopped nocodb/nocodb:latest\ndocker network create wekan-net\ndocker run -d --name wekan-db --network wekan-net --restart=always mongo:5\ndocker run -d --name wekan --network wekan-net --restart=always \\\n  -e MONGO_URL=mongodb://wekan-db:27017/wekan \\\n  -e ROOT_URL=http://localhost:8080 -p 8080:8080 wekanteam/wekan\ngit clone https://github.com/jitsi/docker-jitsi-meet && cd docker-jitsi-meet && cp env.example .env && docker compose up -d\ndocker run -d --name joplin -p 22300:22300 -e APP_PORT=22300 -e APP_BASE_URL=http://localhost:22300 --restart unless-stopped joplin/server:latest', 'note': None}]
